INSERT INTO `movies` (`id`, `tmdb_id`, `title`, `overview`, `poster_path`, `release_date`, `genre_ids`, `popularity`, `created_at`) VALUES
(1, 1226863, 'Super Mario Galaxy: O Filme', 'Depois de salvar o Reino dos Cogumelos, Mario e seus amigos se encontram em uma missão intergaláctica para deter um novo vilão ameaçador.', '/b3WeTp42eJSRuE4UZfyPCOJW4c.jpg', '2026-04-01', '[10751,35,12,14,16]', 411.15, '2026-05-11 16:06:01'),
(2, 1007757, 'Como Mágica', 'Uma pequena criatura da floresta e um pássaro majestoso trocam de corpo e precisam se unir para sobreviver à aventura mais incrível de suas vidas.', '/7FBnCkYzHlVHEtuzTEiGgFhs8EQ.jpg', '2026-05-01', '[12,16,10751,14]', 444.18, '2026-05-11 16:06:01'),
(3, 1318447, 'O Jogo do Predador', 'Uma mulher em luto embarca sozinha em uma aventura pela natureza selvagem da Austrália, mas acaba se envolvendo em um jogo cruel de gato e rato com um assassino.', '/mBcYPIubRBPTnTwWdj8OuEC1NHJ.jpg', '2026-04-24', '[28,53]', 327.84, '2026-05-11 16:06:01'),
(4, 10867, 'Malèna', 'Em 1941, numa pequena vila localizada na Sicília, um grupo de garotos de 13 anos de idade nutre uma profunda paixão por Malena (Monica Bellucci), a viúva de um soldado local, despertando uma história de amor, perda e coragem.', '/aGK0x9RblIUqkLp6xKYMSttlqMn.jpg', '2000-10-27', '[18]', 158.53, '2026-05-11 16:06:01'),
(5, 1198994, 'Socorro!', 'Após um acidente aéreo, um chefe e uma funcionária que se odeiam são os únicos sobreviventes. Isolados numa ilha deserta, eles precisam decidir se cooperam ou competem para escapar, mas é difícil deixar para trás os conflitos do escritório.', '/rpU5DGrTVdqcygZBB9npt1WMFch.jpg', '2026-01-22', '[27,53,35]', 246.02, '2026-05-11 16:06:01'),
(6, 350, 'O Diabo Veste Prada', 'Andrea Sachs é uma jovem que conseguiu um emprego na Runaway Magazine, a mais importante revista de moda de Nova York. Ela passa a trabalhar como assistente de Miranda Priestly, principal executiva da revista. Apesar da chance que muitos sonhariam em conseguir, logo Andrea nota que trabalhar com Miranda não é tão simples assim.', '/pcfB2TNsR9caaSSMrZIc9FoUWrp.jpg', '2006-06-29', '[18,35]', 284.23, '2026-05-11 16:06:01'),
(7, 687163, 'Devoradores de Estrelas', 'Professor de ciências do ensino fundamental acorda em espaçonave a anos-luz da Terra sem memória de como foi parar ali. Aos poucos, lembra que foi recrutado para uma missão na qual precisa investigar o motivo pelo qual o Sol está morrendo.', '/bOzG3SG6gBxHGGHYiq7xXeNb1bG.jpg', '2026-03-15', '[878,12]', 308.28, '2026-05-11 16:06:01'),
(8, 931285, 'Mortal Kombat 2', 'Os campeões favoritos dos fãs – agora acompanhados pelo próprio Johnny Cage – são colocados uns contra os outros numa sangrenta e derradeira batalha, sem regras ou limites, para derrotar o governo sombrio de Shao Kahn.', '/l2OwwZBGZxJDWRglKqbFhx7Eok.jpg', '2026-05-06', '[28,14,12]', 223.54, '2026-05-11 16:06:01'),
(9, 1266127, 'Casamento Sangrento: A Viúva', 'A noiva retorna em uma nova e sinistra rodada do tradicional jogo de esconde-esconde, agora com elementos sobrenaturais e demoníacos.', '/l08o8b3NAPxDzJca9ZF0fdQvbaz.jpg', '2026-03-19', '[27,35]', 190.35, '2026-05-11 16:06:01'),
(10, 1523145, 'Um Amor de Mentiras', 'Polina, uma estudante do ensino médio, é salva do bullying em sua nova escola e faz um acordo com o principal valentão, Bars: ele deve fingir ser seu namorado e protegê-la, e ela deve fazer tudo o que ele mandar. Durante esse jogo, o casal desenvolve sentimentos verdadeiros, mas sua família e colegas de classe têm motivos para separá-los.', '/hXNn25hE2SH2kHMPVOLjqDISSxf.jpg', '2026-03-26', '[10749,18]', 235.09, '2026-05-11 16:06:01'),
(11, 936075, 'Michael', 'A história da vida de Michael Jackson além da música, traçando sua jornada desde a descoberta de seu talento extraordinário como líder dos Jackson Five até o artista visionário cuja ambição criativa impulsionou uma busca implacável para se tornar o maior artista do mundo.', '/dueFqKLvjftnELZaGYwY7xinfaI.jpg', '2026-04-22', '[10402,18]', 168.44, '2026-05-11 16:06:01'),
(12, 1327819, 'Cara de Um, Focinho de Outro', 'Mabel é uma jovem amante da natureza que tenta impedir o prefeito Jerry de construir uma rodovia que destruirá suas florestas locais. Graças a um experimento secreto de troca de cérebros, Mabel consegue transferir sua mente para um castor robô e segue para um lago, onde refugiados da industrialização invasora desembarcaram. Lá, ela tenta convencer os animais, liderados pelo castor majestoso Rei George, a se juntarem a ela e impedirem a construção da rodovia.', '/ftPFJBGbldoWiiPrmesW96zBzdH.jpg', '2026-03-04', '[16,12,35,10751,878]', 162.30, '2026-05-11 16:06:02'),
(13, 1669050, 'Tayuan 2', '', '/gkHNa8q3RNhgj2EMuoYWJUHsMa6.jpg', '2026-04-17', '[18]', 143.64, '2026-05-11 16:06:02'),
(14, 1630423, 'Meu Querido Assassino', 'Perseguida por ter um tipo sanguíneo raro, uma jovem encontra proteção nos braços de um assassino perigoso. Juntos, eles lutam para sobreviver.', '/9ZfPvLEx1xcuTkfAtrVyIbA5Vaw.jpg', '2026-05-06', '[28,18,10749]', 206.62, '2026-05-11 16:06:02'),
(15, 83533, 'Avatar: Fogo e Cinzas', 'Após a devastadora guerra contra a RDA e a perda de seu filho mais velho, Jake Sully e Neytiri enfrentam uma nova ameaça em Pandora: o Povo das Cinzas, uma tribo Na\'vi violenta e sedenta por poder, liderada pela implacável Varang. A família de Jake deve lutar por sua sobrevivência e pelo futuro de Pandora em um conflito que os leva aos seus limites emocionais e físicos.', '/9k2zKeUfcKkAz1dGt5MP6dZMm4G.jpg', '2025-12-17', '[878,12,14]', 162.52, '2026-05-11 16:06:02'),
(16, 318256, 'Hot Girls Wanted', 'Apresentado no Festival Sundance de Cinema de 2015, este documentário do produtor Rashida Jones investiga a indústria do pornô “amador” e as mulheres exploradas.', '/75ot83QOkc02vujyzmIbumQCU6Y.jpg', '2015-01-24', '[99]', 229.80, '2026-05-11 16:06:02'),
(17, 1314481, 'O Diabo Veste Prada 2', 'Miranda Priestly navega por sua carreira em meio ao declínio das publicações tradicionais de revistas. Ela se confronta com Emily Charlton, sua ex-assistente, agora uma influente executiva de um grupo de luxo, que detém verbas publicitárias de que Miranda Priestly precisa desesperadamente.', '/50yWyY981TyUHhoxxSEKwO70FmQ.jpg', '2026-04-29', '[35,18]', 115.01, '2026-05-11 16:06:02'),
(18, 1613798, 'Vingança Brutal', 'Quando sua esposa é brutalmente assassinada, Carlos Estrada, herói condecorado das forças especiais, passa a viver com apenas um propósito: vingança. Depois que uma reviravolta do destino o torna um milionário, Carlos transforma sua fortuna em um arsenal e, com seus soldados de maior confiança, inicia uma caçada incansável pelos responsáveis.', '/88P3qzWBRYvI0K5fNtqwwXQsvwi.jpg', '2026-02-26', '[28,53]', 122.51, '2026-05-11 16:06:02'),
(19, 1292695, 'Eles Vão te Matar', 'Uma mulher aceita um emprego como governanta em um arranha-céu de Nova York, sem saber da história de desaparecimentos do prédio. Ela logo percebe que a comunidade está envolta em mistério.', '/kPiqEJ8reCWKZXIWgweQd6eR2tP.jpg', '2026-03-25', '[28,35,27]', 117.39, '2026-05-11 16:06:02'),
(20, 1292415, 'Beast', 'Um pescador comercial que luta para sustentar a família e vingar a morte do irmão enfrenta um adversário perigoso em uma luta de artes marciais mistas.', '/7NrvUI3vnW8H3rD7ExKcTL7KRcQ.jpg', '2026-04-10', '[28,18]', 125.25, '2026-05-11 16:06:02'),
(21, 550, 'Clube da Luta', 'Um homem deprimido que sofre de insônia conhece um estranho vendedor de sabonetes chamado Tyler Durden. Eles formam um clube clandestino com regras rígidas onde lutam com outros homens cansados de suas vidas mundanas. Mas sua parceria perfeita é comprometida quando Marla chama a atenção de Tyler.', '/mCICnh7QBH0gzYaTQChBDDVIKdm.jpg', '1999-10-15', '[]', 29.19, '2026-05-11 16:07:03'),
(22, 49521, 'O Homem de Aço', 'Um garoto descobre que não é deste planeta e que tem poderes extraordinários. Quando se torna adolescente, viaja para descobrir de onde veio e para o quê foi enviado a fazer. Mas o herói nele deve emergir se quiser salvar o mundo da aniquilação e se tornar o símbolo de esperança para toda a humanidade.', '/cheo9jDPfyW1GevfPjXtnO91KNe.jpg', '2013-06-12', '[28,12,878]', 13.44, '2026-05-12 05:47:20'),
(23, 73861, 'A Serbian Film - Terror sem Limites', 'Milos (Srdjan Todorovic), um ator pornô aposentado, é convidado a participar de um filme erótico de arte. Como enfrenta problemas financeiros ele aceita a oferta, sem imaginar que está entrando num \"snuff movie\" da sua própria vida.', '/r7MR0GmKe4pE0OX43LXMztNz8Z8.jpg', '2010-01-06', '[80,27,53]', 13.60, '2026-05-12 05:47:20'),
(24, 666277, 'Vidas Passadas', 'Nora e Hae Sung são amigos de infância profundamente conectados que se separam quando a família de Nora emigra da Coreia do Sul. Duas décadas depois, se reencontram em Nova York numa semana fatídica enquanto confrontam noções de destino, amor e as escolhas que fazem uma vida, neste romance moderno comovente.', '/toSI71gFF11VnLfz2uiNx6jjNUF.jpg', '2023-06-02', '[18,10749]', 11.05, '2026-05-12 05:47:20'),
(25, 411, 'As Crônicas de Nárnia: O Leão, a Feiticeira e o Guarda-Roupa', 'Durante os bombardeios da Segunda Guerra Mundial de Londres, quatro irmãos ingleses são enviados para uma casa de campo onde eles estarão seguros. Um dia, Lucy encontra um guarda-roupa que a transporta para um mundo mágico chamado Nárnia. Depois de voltar, ela logo volta a Nárnia com seus irmãos, Peter e Edmund, e sua irmã, Susan. Lá eles se juntam ao leão mágico, Aslan, na luta contra a Feiticeira Branca.', '/sDBziWxSTavCNjbayaXaDDwmTiQ.jpg', '2005-12-07', '[12,10751,14]', 13.68, '2026-05-12 05:47:20'),
(26, 1275779, 'Dia D', 'A existência de vida extraterrestre torna-se uma realidade inegável para todos os habitantes da Terra em um único instante. O mundo entra em colapso quando uma meteorologista, em plena transmissão ao vivo, é dominada por uma força invisível, perdendo a fala e emitindo sons perturbadores. Enquanto fenômenos inexplicáveis e sinais de controle mental em massa se espalham, um informante tenta expor segredos governamentais guardados por décadas. Diante da prova definitiva de que a humanidade não está sozinha, o pânico e o fascínio tomam conta de uma civilização confrontada pelo desconhecido.', '/pmff1wjKrgJi92PPr346lAifzlg.jpg', '2026-06-10', '[9648,878,53]', 14.22, '2026-05-12 05:47:20'),
(27, 1325678, 'O Tesouro de Sarah', 'Uma jovem afro-americana, nascida no início do século XX, acredita que há petróleo em suas terras, e a intuição se confirma. Mas, quando chegam exploradores sem escrúpulos, ela precisa recorrer à sua família e a perfuradores independentes para manter o controle das terras.', '/vHIPqxm9qYMbXWkhSoFiGLraFvD.jpg', '2025-11-06', '[18]', 13.40, '2026-05-12 05:47:20'),
(28, 854, 'O Máskara', 'Em Edge City vive Stanley Ipkiss, um cara decente que trabalha em um banco, mas é socialmente desajeitado e sem muito sucesso com as mulheres. Após um dos piores dias da sua vida, ele acha no mar a estranha máscara de Loki, um deus escandinavo. Quando Stanley coloca a máscara, se transforma em \"O Máskara\", um ser com o rosto verde que possui a coragem para fazer as coisas mais arriscadas e divertidas que Stanley receia fazer, inclusive flertar com Tina Carlyle, a bela e sensual cantora que se apresenta no Coco Bongo, a discoteca do momento. O Máskara tem velocidade sobre-humana e um humor não-convencional e, enquanto isto, o gângster Dorian Tyrrell, que namora Tina, se esforça para destruir o Máskara e se apoderar da máscara para usar seus poderes para o mal.', '/zLLC7AldfrYUot7lsw3ePFSs87e.jpg', '1994-07-29', '[35,14,80,10749]', 12.30, '2026-05-12 05:47:20'),
(29, 1007401, 'Mortal Kombat Legends: Cegueira Glacial', 'Determinado a assumir Earthrealm, Kano ataca violentamente cidade após cidade com a ajuda de três mercenários de sangue frio do Black Dragon. Aqueles que não se submetem são aniquilados, mas um jovem não se ajoelha para Kano: Kenshi.', '/pJvZHaduX9GeASdZ16hc8O9JCWz.jpg', '2022-10-09', '[16,28,14]', 12.79, '2026-05-12 05:47:20'),
(30, 507086, 'Jurassic World: Domínio', 'Quatro anos após a destruição da Ilha Nublar, os dinossauros agora vivem – e caçam – ao lado de humanos em todo o mundo. Esse frágil equilíbrio remodelará o futuro e determinará, de uma vez por todas, se os seres humanos continuarão sendo os principais predadores em um planeta que agora compartilham com as criaturas mais temíveis da história.', '/7qeiCNSmzrkcEyIWi8sIcsjrOyW.jpg', '2022-06-01', '[12,878,53]', 12.79, '2026-05-12 05:47:20'),
(31, 381284, 'Estrelas Além do Tempo', 'Ano 1961, em plena Guerra Fria, Estados Unidos e União Soviética disputam a supremacia na corrida espacial ao mesmo tempo em que a sociedade norte-americana lida com uma profunda cisão racial, entre brancos e negros. Tal situação é refletida também na NASA, onde um grupo de funcionárias negras é obrigada a trabalhar a parte. É lá que estão Katherine Johnson, Dorothy Vaughn e Mary Jackson, grandes amigas que, além de provar sua competência dia após dia, precisam lidar com o preconceito arraigado para que consigam ascender na hierarquia da NASA.', '/6A1Jn0tooQYgi2C8sNz5OaIW98C.jpg', '2016-12-10', '[18,36]', 12.46, '2026-05-12 05:47:20'),
(32, 5879, 'O Império dos Sentidos', 'A história de uma ex-prostituta que envolve-se em um caso de amor obsessivo com o senhorio de uma propriedade onde ela trabalha como criada. O que começa como uma diversão inconseqüente transforma-se em uma paixão que ultrapassa quaisquer limites.', '/nnOvs5nFTdYa33eCREMwDniPbm9.jpg', '1976-09-15', '[18,10749]', 14.06, '2026-05-12 05:47:20'),
(33, 1891, 'Guerra nas Estrelas: O Império Contra-Ataca', 'As forças imperais comandadas por Darth Vader lançam um ataque contra os membros da resistência, que são obrigados a fugir. Enquanto isso Luke Skywalker tenta encontrar o Mestre Yoda, que poderá ensiná-lo a dominar a \"Força\" e torná-lo um cavaleiro jedi. No entanto, Darth Vader planeja levá-lo para o lado negro da \"Força\".', '/dLGT8b4Ut10z44uYLaip4QiwKta.jpg', '1980-05-20', '[12,28,878]', 13.12, '2026-05-12 05:47:20'),
(34, 1734, 'O Retorno da Múmia', 'Rick e Evelyn O\'Connell estão morando na Londres de 1935, onde criam o filho. Quando uma série de eventos revela o corpo de Imhotep ressuscitado, os O\'Connell iniciam uma corrida desesperada para salvar o mundo do mal e resgatar o filho antes que seja tarde demais.', '/34X3xSSriMVdHHO9EEpe8thhDCC.jpg', '2001-05-04', '[12,28,14]', 11.88, '2026-05-12 05:47:21'),
(35, 105864, 'O Bom Dinossauro', 'Em um mundo onde os dinossauros e os humanos coexistem, um jovem apatossauro e um garoto neandertal criam uma amizade única e vivem aventuras inesquecíveis.', '/h85jXVapDFhsDvlsrmuMJkfvXSj.jpg', '2015-11-14', '[12,16,10751]', 11.44, '2026-05-12 05:47:21'),
(36, 85, 'Indiana Jones e os Caçadores da Arca Perdida', 'Em 1936, o professor e arqueólogo Indiana Jones é contratado pelo governo para encontrar a Arca da Aliança, que segundo as escrituras bíblicas conteria \"Os Dez Mandamentos\" que Deus revelou a Moisés no Monte Horeb. Mas como a lenda diz que o exército que a possuir será invencível, Indiana Jones terá um adversário de peso na busca pela arca perdida: o regime nazista de Adolf Hitler.', '/mtf7iKZRdsL6qbbCnd2TAxOfJYg.jpg', '1981-06-12', '[12,28]', 12.10, '2026-05-12 05:47:21'),
(37, 82702, 'Como Treinar o seu Dragão 2', 'Cinco anos após convencer os habitantes de seu vilarejo que os dragões não devem ser combatidos, Soluço convive com seu dragão Fúria da Noite, e estes animais integraram pacificamente a rotina dos moradores da ilha de Berk. Entre viagens pelos céus e corridas de dragões, Soluço descobre uma caverna secreta, onde centenas de novos dragões vivem. O local é protegido por Valka, mãe de Soluço, que foi afastada do filho quando ele ainda era um bebê. Juntos, eles precisarão proteger o mundo que conhecem do perigoso Drago Bludvist, que deseja controlar todos os dragões existentes.', '/bj6DeGQeaJa3ert4bjCBqLSZdHz.jpg', '2014-06-05', '[14,28,12,16,10751]', 11.70, '2026-05-12 05:47:21'),
(38, 1314786, 'Agente Zeta', 'Quatro ex-agentes do serviço secreto espanhol são assassinados simultaneamente ao redor do mundo. A CNI descobre que todos participaram da \"Operação Ciénaga\" décadas antes na Colômbia. Zeta, o melhor agente da CNI, deve encontrar e proteger o único sobrevivente em sua mais perigosa missão, até então. A agente da Colômbia, Alfa, se juntará a Zeta, e parece saber mais sobre a \"Ciénaga\" do que ele.', '/zU20MrtOAYon07ULE9wFxUeaaqd.jpg', '2026-03-20', '[18,53]', 12.18, '2026-05-12 05:47:21'),
(39, 18, 'O Quinto Elemento', 'No século XXIII, um motorista de taxi de Nova York se envolve em uma aventura na qual tem de deter um ser demoníaco que percorre a galáxia a cada cinco mil anos. Se nada for feito, a Terra será destruída. Mas para isto, ele precisa encontrar quatro pedras antigas que representam os elementos e colocá-las em volta de uma bela mulher, que é o quinto elemento.', '/t2fanPUgCGty1tmU9t3jtYEOEMS.jpg', '1997-05-02', '[878,28,12]', 11.88, '2026-05-12 05:47:21'),
(40, 232672, 'Juntos e Misturados', 'Após um encontro desastroso, os pais solteiros Lauren e Jim concordam apenas com uma coisa, eles nunca vão querer se encontrar de novo. Mas quando ambos, separadamente, têm a oportunidade de viajar com suas famílias para as férias dos seus sonhos, acabam tendo que dividir a mesma suíte em um luxuoso resort safari africano por uma semana inteira...', '/tD0UJtt237FAST3rD1htrGLBKAH.jpg', '2014-05-21', '[35,10749]', 14.27, '2026-05-12 05:47:21'),
(41, 1575337, 'Kaguya: A Princesa Espacial', 'A vida de Iroha sai da órbita quando a fugitiva Kaguya chega direto da lua e a convence a se apresentar com ela em um mundo virtual.', '/9lHbzF8h1do99LlIis8iemMOZSj.jpg', '2026-01-22', '[16,14,10402,878]', 12.39, '2026-05-12 05:47:21'),
(42, 436270, 'Adão Negro', 'Quase 5.000 anos depois de ter sido concedido com os poderes onipotentes dos deuses egípcios - e de ter sido preso, - Adão Negro se ergue de seu túmulo, pronto para trazer sua justiça ao mundo moderno.', '/ZTzxi5aKXua2eIlmaMbxxcoW7v.jpg', '2022-10-19', '[28,12,878]', 15.76, '2026-05-12 05:53:21'),
(43, 796, 'Segundas Intenções', 'Sem querer, Annette passa a ser objeto de um diabólico jogo sexual para os irmãos de criação Sebastian e Kathryn ao escrever um artigo na revista \"Seventeen\" sobre como pretende permanecer virgem até se casar. Porém, Sebastian recebe mais do que esperava quando tenta levar Annette para cama. A incursão do jovem faz parte de uma aposta que ele fez com a irmã manipuladora, que adora passar o tempo tentando arruinar a vida amorosa dos amigos.', '/uG1CczBQtAFxBvRIAT7R4oSaIaz.jpg', '1999-03-05', '[18,10749]', 15.75, '2026-05-12 05:53:22'),
(44, 566525, 'Shang-Chi e a Lenda dos Dez Anéis', 'Shang-Chi precisa confrontar o passado que pensou ter deixado para trás. Ao mesmo tempo, ele é envolvido em uma teia de mistérios da organização conhecida como Dez Anéis.', '/fojnVuvt181l7LxsJDxCQfWSKfh.jpg', '2021-09-01', '[28,12,14]', 15.73, '2026-05-12 05:53:22'),
(45, 1100988, 'Extermínio: A Evolução', 'Já se passaram quase três décadas desde que o vírus da raiva escapou de um laboratório de armas biológicas. Agora, sob uma quarentena rigidamente imposta, alguns conseguiram encontrar maneiras de sobreviver em meio aos infectados. Um desses grupos vive em uma pequena ilha, ligada ao continente por uma única passagem fortemente protegida. Quando um dos membros parte em uma missão rumo ao sombrio coração do continente, ele descobre segredos, maravilhas e horrores que transformaram não apenas os infectados, mas também outros sobreviventes.', '/2K5LCXOqlbzRu7mWHbDnLdDQj6I.jpg', '2025-06-18', '[27,53,878]', 15.72, '2026-05-12 05:53:22'),
(46, 14161, '2012', 'Bilhões de habitantes da Terra não estão cientes de que o planeta tem uma data de expiração. Com os avisos de um cientista norte-americano, os líderes mundiais começam os preparativos secretos para a sobrevivência de alguns membros da sociedade. Quando o cataclisma global finalmente ocorre, o fracassado escritor Jackson Curtis tenta levar sua família para um lugar seguro quando o mundo começa a desmoronar.', '/3OyC6YVOrTqXpSjgXQ1L8LDrUFp.jpg', '2009-10-10', '[28,12,878]', 15.69, '2026-05-12 05:53:22'),
(47, 829557, '365 Dias: Hoje', 'Em 365 Dias: Hoje, após os acontecimentos de 365 Dias, Laura Biel se casa com Don Massimo, o chefe da máfia siciliana que a sequestrou. Sua vida parece um conto de fadas: ela tem um marido amoroso, uma casa linda e um bebê a caminho. Mas Massimo tem muitos inimigos, e eles sabem que a melhor maneira de lhe causar dor é ferir aqueles que ama. Depois de um mal-entendido conjugal, Laura e sua melhor amiga, Olga, fogem da Sicília para a Polônia natal. Mas sem a proteção do marido, Laura é sequestrada por Marcelo \"Nacho\" Matos, filho do chefe da máfia rival, e levada para as Ilhas Canárias pela máfia espanhola. Agora Massimo moverá qualquer montanha para resgatá-la. Mas o que o chefe da máfia siciliana não espera é que Laura começa a ter sentimentos pelo seu raptor, lindo e extremamente perigoso, enquanto é mantida refém.', '/3104lH1U1XfUXo0ZLawnIjXS0NC.jpg', '2022-04-26', '[10749,18]', 15.66, '2026-05-12 05:53:22'),
(48, 151026, 'A Colegial Seduz o Professor', 'Para estudar em paz, longe das distrações da cidade, Angela (Gloria Guida) é enviada pelo seu pai para casa do tio Puglia (Lino Banfi), numa pequena vila. Rapidamente, os colegas apaixonam-se por ela, assim como o seu primo, seu tio e um Professor que é constantemente vitima de piadas, por parte dos alunos.', '/ll7zJmMPglc6P7x6RYzJptZSbmm.jpg', '1979-08-09', '[35]', 15.63, '2026-05-12 05:53:22'),
(49, 675, 'Harry Potter e a Ordem da Fênix', 'Lord Voldemort está de volta, mas o Ministério da Magia está fazendo tudo a seu alcance para impedir que a comunidade mundial de bruxos descubra isso – incluindo indicar a oficial do Ministério, Dolores Umbridge, como a nova professora de Defesa Contra as Artes das Trevas de Hogwarts. Quando Umbridge se recusa a ensinar a prática de mágica defensiva, Rony e Hermione convencem Harry a secretamente treinar um grupo de estudantes para a guerra de magia que está prestes a estourar.', '/tIf9aUyNljda9MG1pjlOLHCZ3b0.jpg', '2007-07-08', '[12,14]', 15.60, '2026-05-12 05:53:22'),
(50, 840430, 'Os Rejeitados', 'Um professor mal-humorado de uma prestigiada escola americana é forçado a cuidar de um grupo de alunos que não tem para onde ir durante as férias de Natal. Ele acaba criando um vínculo com um dos estudantes e com a cozinheira da escola, que acaba de perder seu filho no Vietnã.', '/ek4FmIkKlH30xthKs2ANqrV7SOI.jpg', '2023-10-27', '[18,35]', 15.55, '2026-05-12 05:53:22'),
(51, 1072790, 'Todos Menos Você', 'Bea e Ben parecem o casal perfeito, mas depois de um primeiro encontro incrível, algo acontece que transforma sua atração ardente em gelo - até que eles se encontram inesperadamente juntos em um casamento na Austrália.  Então eles fazem o que dois adultos maduros fariam: fingem ser um casal.', '/iKOEAPkb5EyCPmAgByYNeAoG5uc.jpg', '2023-12-21', '[10749,35]', 15.54, '2026-05-12 05:53:22'),
(52, 604079, 'A Longa Marcha: Caminhe ou Morra', 'Um grupo de adolescentes compete em uma competição anual conhecida como \"A Longa Marcha\", onde eles devem manter uma certa velocidade de caminhada ou levar um tiro.', '/qE0XKOHZvXtiM4aBLlTPUVZiIc5.jpg', '2025-09-10', '[878,53,27]', 15.53, '2026-05-12 05:53:22'),
(53, 1865, 'Piratas do Caribe: Navegando em Águas Misteriosas', 'O passado do capitão Jack Sparrow volta a alcançá-lo quando ele cruza com Angelica, uma bonita pirata que Jack, um dia, amou e depois abandonou. Ela, então, o força a acompanhá-la ao navio Vingança da Rainha Ana, do famoso Barba Negra. Junto com uma tripulação de zumbis, o trio parte em busca da lendária Fonte da Juventude. Mas o rival de Jack, Barbossa, também cobiça a fonte, assim como um navio espanhol.', '/blt7kBXEk1HgJjCTusaUMQ7BCTY.jpg', '2011-05-15', '[12,28,14]', 15.53, '2026-05-12 05:53:22'),
(54, 128, 'Princesa Mononoke', 'Um príncipe infectado por uma doença sabe que irá morrer, a menos que encontre a cura. Sendo a sua última esperança, segue para o leste e, durante o caminho, encontra animais da floresta lutando contra a sua exploração, liderados pela princesa Mononoke.', '/7EadOwHmyQgOnlghRiWBygNtnjl.jpg', '1997-07-12', '[12,14,16]', 15.49, '2026-05-12 05:53:23'),
(55, 1197137, 'O Telefone Preto 2', 'Quatro anos após escapar de The Grabber, Finney Blake luta com sua vida após o cativeiro. Quando sua irmã Gwen começa a receber ligações em sonhos do telefone preto e a ter visões perturbadoras de três garotos sendo perseguidos em um acampamento de inverno conhecido como Alpine Lake, os irmãos se determinam a desvendar o mistério e confrontar um assassino que se tornou mais poderoso na morte e mais significativo para eles do que qualquer um poderia imaginar.', '/p3epSUdF9qSWWHTBlA3mJ0w2i2Y.jpg', '2025-10-15', '[27,53]', 15.49, '2026-05-12 05:53:23'),
(56, 1248226, 'Um Dia Fora de Controle', 'Quando o contador desempregado Brian leva seu filho para brincar com o filho de Jeff, pai que fica em casa, ele espera um dia tranquilo. Em vez disso, eles acabam perseguidos por mercenários, e Brian — totalmente despreparado — precisa sobreviver a um obstáculo absurdo atrás do outro. A vida de pai de família vira um caos de filme de ação nesta aventura hilária.', '/auLOTlulof19GSPrNomyG7myfzN.jpg', '2025-11-04', '[28,35,10751]', 15.47, '2026-05-12 05:53:23'),
(57, 945961, 'Alien: Romulus', 'Enquanto vasculham as profundezas de uma estação espacial abandonada, um grupo de jovens colonizadores espaciais se depara com a forma de vida mais aterrorizante do universo.', '/jB0W9tn4w07MFn7sTfqRTBLVytF.jpg', '2024-08-13', '[27,878]', 15.44, '2026-05-12 05:53:23'),
(58, 679, 'Aliens: O Resgate', 'Cinquenta e quatro anos após escapar da \"Nostromo\", a tenente Ripley é encontrada a flutuar, perdida no espaço, ainda adormecida. De volta ao nosso planeta, ela conta tudo o que lhe aconteceu, mas ninguém acredita realmente nela, ou lhe parece dar crédito, até que uma colônia de humanos, criada no planeta onde ela encontrou o primeiro Alienígena, deixa de emitir comunicações subitamente. Ela então é convocada para auxiliar uma expedição militar ao local, sendo a única aparentemente consciente de que o pesadelo está longe do fim.', '/dopA5H3VYKcTE1lDXkTwRx7uy2G.jpg', '1986-07-18', '[28,53,878]', 15.40, '2026-05-12 05:53:23'),
(59, 284054, 'Pantera Negra', 'O príncipe T\'Challa retorna a Wakanda para ser coroado rei. Assumindo o manto de Pantera Negra, ele vai à caça de um vilão que roubou um precioso metal de seu país.', '/ubXNpxL2ASSzY0f8Hxv08pOsV2L.jpg', '2018-02-13', '[28,12,878]', 15.39, '2026-05-12 05:53:23'),
(60, 2105, 'American Pie: A Primeira Vez é Inesquecível', 'Jim Kevin, Oz e Finch são quatro amigos às vésperas do baile de formatura de escola. Entre tentativas frustradas de fazer sexo com as namoradas, vigiar garotas nuas pela Internet e até atacar uma torta recém-saída do forno, os rapazes fazem um pacto: deixar a virgindade para trás antes do baile de formatura. Começam, então, as investidas mais hilariantes em busca de sexo e, principalmente, mulheres.', '/4GxuPJxUcArRpfBGJL6BG3B4Cb9.jpg', '1999-07-09', '[35,10749]', 15.39, '2026-05-12 05:53:23'),
(61, 283995, 'Guardiões da Galáxia - Vol. 2', 'Os Guardiões precisam lutar para manter sua recém descoberta família unida, enquanto descobrem os mistérios sobre o verdadeiro pai de Peter Quill.', '/i2UpjQ5CI9STnyv1UZitM6QBqwv.jpg', '2017-04-19', '[878,12,28]', 15.36, '2026-05-12 05:53:23'),
(62, 1499885, 'The Red Book Ritual: Gates of Hell', '', '/dOLRsvnjOB6rCx6olyRsMT92PxI.jpg', '2025-09-18', '[27]', 22.75, '2026-05-12 05:53:59'),
(63, 805681, 'Deepfrozen', '', '/iJCtCqjF68TPkMwXceHK4f59WHR.jpg', '2006-09-07', '[35]', 25.65, '2026-05-12 05:53:59'),
(64, 597, 'Titanic', 'Um artista pobre e uma jovem rica se conhecem e se apaixonam na fatídica jornada do Titanic, em 1912. Embora esteja noiva do arrogante herdeiro de uma siderúrgica, a jovem desafia sua família e amigos em busca do verdadeiro amor.', '/As0zX43h3w6kD2NS4uVHu9HKdEh.jpg', '1997-12-18', '[18,10749]', 27.49, '2026-05-12 05:53:59'),
(65, 1061474, 'Superman', 'Superman, um jovem repórter de Metrópolis, embarca em uma jornada para reconciliar sua herança kryptoniana com sua criação humana como Clark Kent.', '/v8ezJI3qfEv4OYq8AWSp4inFIwE.jpg', '2025-07-09', '[878,12,28]', 27.89, '2026-05-12 05:53:59'),
(66, 774444, 'Cinematographer', '', '/rLDuY9fphBYNHZdu1Fu0qsfeHqN.jpg', '2020-12-04', '[99]', 27.56, '2026-05-12 05:53:59'),
(67, 9823, 'Mortal Kombat: A Aniquilação', 'Shao Kahn, o imperador do Outworld, desrespeita todas as regras de Mortal Kombat e abre ilegalmente as portas entre o seu reino e a Terra. Se elas permanecerem abertas por sete dias, será o fim dos humanos! Assim, um grupo de guerreiros tem seis dias para fechar as portas e salvar a Terra, mas para isto precisam enfrentar e vencer as demoníacas forças do Outworld.', '/rfrpLH39VskMfi9k0JXD36e0jJ5.jpg', '1997-11-11', '[28,14,878]', 29.50, '2026-05-12 05:53:59'),
(68, 258216, 'Ninfomaníaca: Volume 1', 'Bastante machucada e largada em um beco, Joe é encontrada por um homem mais velho, Seligman, que lhe oferece ajuda. Ele a leva para sua casa, onde possa descansar e se recuperar. Ao despertar, Joe começa a contar detalhes de sua vida para Seligman. Assumindo ser uma ninfomaníaca e que não é, de forma alguma, uma pessoa boa, ela narra algumas das aventuras sexuais que vivenciou para justificar o porquê de sua auto avaliação.', '/t2CHmKC6B3H78YikUXB70BYAvoI.jpg', '2013-12-25', '[18]', 28.24, '2026-05-12 05:53:59'),
(69, 137051, 'Midnight Matinee', '', '/czam6wq46B9UCZvq85vicElckFq.jpg', '1988-10-12', '[27,9648,53,10770]', 26.52, '2026-05-12 05:53:59'),
(70, 1233413, 'Pecadores', 'Dispostos a deixar suas vidas conturbadas para trás, irmãos gêmeos retornam à sua cidade natal para recomeçar suas vidas do zero, quando descobrem que um mal ainda maior está à espera deles para recebê-los de volta.', '/v0Ljeti537c6cNKweuEN0iaU3x4.jpg', '2025-04-16', '[27,28,53]', 27.17, '2026-05-12 05:53:59'),
(71, 866398, 'Beekeeper: Rede de Vingança', 'Clay está em busca de vingança e não vai parar até acabar com o sistema criminoso responsável pela morte de sua amiga. O plano brutal de Clay, um ex-agente de uma organização secreta poderosa conhecida como “Beekeepers”, ganha dimensões nacionais envolvendo governos e as instituições mais influentes do mundo. Determinado a fazer justiça com suas próprias mãos, ele está disposto a tudo e não vai poupar ninguém para concluir seu plano.', '/raNfPn7DGbh1Ffwq4Y9BO1Iektv.jpg', '2024-01-08', '[28,80,53]', 25.05, '2026-05-12 05:53:59'),
(72, 1268127, 'Inteligência Humana', 'Ao investigar um cartel russo, um agente sul-coreano fica cara a cara com um agente norte-coreano, e ambos são dragados por perigos e segredos.', '/zmv8yxTmswmMZk7mUktzY9wWXcO.jpg', '2026-02-11', '[53,28,18]', 24.72, '2026-05-12 05:53:59'),
(73, 372058, 'Your name.', 'Mitsuha é a filha do prefeito de uma pequena cidade, mas sonha em tentar a sorte em Tóquio. Taki trabalha em um restaurante em Tóquio e deseja largar o seu emprego. Os dois não se conhecem, mas estão conectados pelas imagens de seus sonhos.', '/eIm2nKC0125GyEPSWl6ODCA9J1S.jpg', '2016-08-26', '[16,10749,18]', 25.32, '2026-05-12 05:54:00'),
(74, 240, 'O Poderoso Chefão: Parte II', 'Após a máfia matar sua família, o jovem Vito foge da sua cidade na Sicília e vai para a América. Vito luta para manter sua família. Ele mata Black Hand Fanucci, que exigia dos comerciantes uma parte dos seus ganhos. Com a morte de Fanucci, o poderio de Vito cresce, mas sua família é o que mais importa para ele. Agora baseado no Lago Tahoe, Michael planeja fazer incursões em Las Vegas e Havana instalando negócios ligados ao lazer, mas descobre que aliados como Hyman Roth estão tentando matá-lo.', '/3ViYPhSAPwH2avQjdMl49F8PklB.jpg', '1974-12-20', '[18,80]', 26.06, '2026-05-12 05:54:00'),
(75, 269955, 'Perigosa Obsessão', 'No verão de 1969, o Coronel Jin Pyeong, preso em um casamento sem amor com Soo Jin, e Jong Ga Heun, a esposa sino-coreana do Capitão Kyung Woo Jin, têm um caso secreto e apaixonado.', '/47PJFu8BBZLMCPzwT2BYSwoKFO9.jpg', '2014-05-14', '[18]', 25.85, '2026-05-12 05:54:00'),
(76, 872585, 'Oppenheimer', 'A história do físico americano J. Robert Oppenheimer, seu papel no Projeto Manhattan e no desenvolvimento da bomba atômica durante a Segunda Guerra Mundial, e o quanto isso mudaria a história do mundo para sempre.', '/1OsQJEoSXBjduuCvDOlRhoEUaHu.jpg', '2023-07-19', '[18,36]', 28.19, '2026-05-12 05:54:00'),
(77, 11, 'Guerra nas Estrelas', 'A princesa Leia é mantida refém pelas forças imperiais comandadas por Darth Vader. Luke Skywalker e Han Solo precisam libertá-la e restaurar a liberdade e a justiça na galáxia.', '/dw7X9YPjjAfIxKHW04V64Bb9TB0.jpg', '1977-05-25', '[12,28,878]', 26.44, '2026-05-12 05:54:00'),
(78, 980477, 'Ne Zha 2: O Renascer da Alma', 'Após uma grande catástrofe, as almas de Ne Zha e Ao Bing são salvas, mas seus corpos enfrentam a ruína. Para lhes dar uma nova vida, Taiyi Zhenren recorre à mística lótus de sete cores em uma ousada tentativa de reconstruí-los e mudar seus destinos.', '/wJnb4ikygiVuYLuvj4b4Jpvudn1.jpg', '2025-01-29', '[16,28,14,12]', 25.52, '2026-05-12 05:54:00'),
(79, 81774, 'A Iniciação', 'O filme mostra a iniciação sexual de Roger um menino de 16 anos que passa férias em uma mansão cheia de mulheres.', '/jp8LYiQzEoUuMqu2lGSZZ1A4Nsf.jpg', '1986-11-04', '[35,18]', 21.53, '2026-05-12 05:54:00'),
(80, 438631, 'Duna', 'Em um futuro distante, planetas são comandados por casas nobres que fazem parte de um império feudal intergalático. Paul Atreides é um jovem cuja família toma o controle do planeta deserto Arrakis, também conhecido como Duna. A única fonte da especiaria Melange, a substância mais importante do cosmos, Arrakis se mostra ser um planeta nem um pouco fácil de governar.', '/uzERcfV2rSHNhW5eViQiO9hNiA7.jpg', '2021-09-15', '[878,12]', 25.45, '2026-05-12 05:54:00'),
(81, 497, 'À Espera de um Milagre', 'Milagres acontecem em lugares inesperados, mesmo no bloco de celas para o corredor da morte na Penitenciária Cold Mountain. Lá, John Coffey, um gentil e gigante prisioneiro com poderes sobrenaturais, traz um senso de espírito e humanidade aos seus guardas e colegas de cela.', '/14hEqW67IiHlKpzKMLUXyktzZIV.jpg', '1999-12-10', '[14,18,80]', 25.91, '2026-05-12 05:54:00'),
(98, 1330021, 'Criaturas Extraordinariamente Brilhantes', 'Uma viúva que trabalha como faxineira noturna em um aquário forma uma amizade improvável com um polvo gigante que a ajuda a desvendar o mistério do desaparecimento de seu filho décadas atrás.', '/iMJaRPY4xx4lScIaIWd67yWJuqc.jpg', '2026-05-07', '[18,9648]', 140.29, '2026-05-12 05:54:23'),
(100, 1297842, 'Um Cabra Bom de Bola', 'Uma pequena cabra com grandes sonhos recebe uma oportunidade única na vida de se juntar aos profissionais e jogar berrobol, um esporte de alta intensidade, misto e de contato total, dominado pelos animais mais rápidos e ferozes do mundo.', '/x0SRTrltSJi1iQiIAUpyvkxnr41.jpg', '2026-02-11', '[16,35,10751]', 119.86, '2026-05-12 05:54:23'),
(102, 911430, 'F1: O Filme', 'Sonny Hayes, a lenda do automobilismo, é persuadido a deixar a aposentadoria para liderar uma equipe de Fórmula 1 em dificuldades—e ser mentor de um jovem piloto famoso—enquanto busca mais uma oportunidade de glória.', '/fMcY5hpVZQ0cLKHvFM1mo6GrAr0.jpg', '2025-06-25', '[28,18]', 41.38, '2026-05-12 05:54:46'),
(103, 91478, 'Minnesota Clay', 'Minnesota Clay é um pistoleiro que foi preso por um crime que não cometeu e que começou a perder a visão na cadeia. Sabendo que é a sua última chance de buscar vingança contra Fox, o ex-parceiro que lhe traiu, ele foge da prisão e vai em busca do rival, apenas para descobrir que ele tornou-se um xerife corrupto e domina toda uma cidade.', '/1Ag1Vsvx7sfxJ2OSmT8rogFkNCw.jpg', '1964-11-12', '[37]', 39.02, '2026-05-12 05:54:46'),
(104, 334535, 'Um Outro Olhar', 'Um homem cego consegue recuperar a sua visão. Porém, fica cego, metaforicamente, pelas suas obsessões superficiais.', '/uyaUbLVoxgJMw3JSGljyOGYpXtz.jpg', '2016-10-09', '[18]', 38.56, '2026-05-12 05:54:46'),
(105, 680493, 'Terror em Silent Hill: Regresso Para o Inferno', 'Quando uma carta misteriosa chama James de volta a Silent Hill em busca de seu verdadeiro amor, ele encontra uma cidade antes reconhecível, transformada por um mal desconhecido. À medida que James se aprofunda na escuridão, ele encontra figuras aterrorizantes, tanto familiares quanto novas, e começa a questionar sua própria sanidade enquanto luta para entender a realidade e se manter firme por tempo suficiente para salvar seu amor perdido.', '/5ZDqTM0ZP3ypmFivTeAnHslV6mY.jpg', '2026-01-21', '[9648,18,27]', 34.13, '2026-05-12 05:54:46'),
(106, 1196067, 'Preparada para a Guerra', 'Cinco anos após uma ruptura na realidade trazer criaturas aterrorizantes para o nosso mundo, a civilização entrou em colapso. A trama acompanha um pai determinado que mantém sua filha escondida em uma ilha isolada para protegê-la. Sabendo que as defesas do local não durarão para sempre, ele a submete a um treinamento rigoroso e brutal de sobrevivência, preparando-a para lutar e garantir o futuro da espécie humana quando a guerra inevitavelmente chegar à porta deles.', '/xL2ixiqqSGGl5zBiBUOyCj9mmgp.jpg', '2025-10-30', '[878,28,27]', 38.65, '2026-05-12 05:54:46'),
(107, 1234731, 'Anaconda', 'Uma crise de meia-idade inspira Doug e Griff a irem até a floresta amazônica para refazer o filme favorito da juventude, mas tudo muda quando uma anaconda gigante de verdade aparece, transformando o cenário comicamente caótico em uma situação mortal. O filme que eles estão morrendo de vontade de fazer? Pode acabar matando-os.', '/hRzpf8QELtzJnMt4SiDoFUmZ9KM.jpg', '2025-12-24', '[12,35,27]', 40.19, '2026-05-12 05:54:46'),
(108, 1476740, 'Influencers', 'Tentando deixar seu passado sombrio para trás, a perigosa CW vive agora uma vida tranquila e idílica no sul da França ao lado de sua namorada, Diane, que não faz ideia dos crimes da companheira. A paz do casal é ameaçada quando elas cruzam o caminho de uma famosa e arrogante influenciadora digital. O encontro desperta os velhos instintos mortais de CW, desencadeando uma nova onda de manipulação e violência, ao mesmo tempo em que uma sobrevivente de seus golpes anteriores fecha o cerco em busca de vingança.', '/nRdjGDxBW60OhzjAtikLgQBwt3B.jpg', '2025-07-26', '[27,53]', 34.49, '2026-05-12 05:54:46'),
(109, 1010581, 'Minha Culpa', 'Noah é obrigada a mudar de cidade, deixando seus amigos e namorado para trás, após sua mãe se casar com um novo marido rico. Lá ela conhece Nick, seu novo meio-irmão, e os dois se apaixonam loucamente, vivendo um grande romance proibido.', '/a59iGvF609yAZ5tfZUoQ3XipeQH.jpg', '2023-06-08', '[18,10749,53]', 40.78, '2026-05-12 05:54:46'),
(110, 425274, 'Truque de Mestre: O 3° Ato', 'Os Quatro Cavaleiros estão de volta com uma nova geração de ilusionistas e uma trama cheia de reviravoltas, mágicas e surpresas, em um truque que envolve a joia mais valiosa do mundo.', '/xUddC5HTjMWmClD007QBWR0BLHY.jpg', '2025-11-12', '[80,53]', 34.85, '2026-05-12 05:54:46'),
(111, 1688652, 'Gary', 'Dois amigos encaram uma viagem a trabalho cheia de desafios inesperados. Enquanto resolvem problemas e se conectam com os moradores, a experiência deixa uma marca inesquecível e oferece um novo olhar sobre a amizade deles.', '/qOOhoxvUDe7lWpPEeh0gFBYpjFe.jpg', '2026-05-05', '[18,35]', 42.42, '2026-05-12 05:54:46'),
(112, 1292662, 'Slaughterhouse On The Hill', '', '/f6C2ckdAXELXbzyY8AoH4lj6udg.jpg', '2024-05-03', '[27]', 32.34, '2026-05-12 05:54:46'),
(113, 80175, 'Entre sábanas', 'Roberto e Paula se conhecem numa boate e depois passam a noite toda juntos em um motel, onde vivem momentos intensos de paixão, amor e drama em apenas algumas horas.', '/opETUc1PXVAngiu8xCe3W2mvKwe.jpg', '2008-04-04', '[18,10749]', 43.59, '2026-05-12 05:54:46'),
(114, 1266992, 'Balinsasayaw', '', '/5gotyf6pPf9ZbDSW0yBLXMpDmmP.jpg', '2024-05-17', '[18]', 38.04, '2026-05-12 05:54:47'),
(115, 803796, 'Guerreiras do K-Pop', 'Quando não estão lotando estádios, as estrelas do K-pop Rumi, Mira e Zoey usam seus poderes secretos para proteger os fãs contra ameaças sobrenaturais.', '/gbdMa7woiuF7IiEB5Spwv5od4oo.jpg', '2025-06-20', '[14,10402,35,16]', 39.03, '2026-05-12 05:54:47'),
(116, 1304313, 'Maldição da Múmia', 'A filha de um jornalista desaparece num deserto sem deixar rastros, deixando a família dilacerada e em luto. Até que, oito anos mais tarde, a jovem garota reaparece, deixando todos chocados. O problema é que esse encontro aparentemente feliz se transforma em um pesadelo de proporções gigantes.', '/ubN87iHY2DyWtwU2JHS0SQ1KqJu.jpg', '2026-04-15', '[27,9648]', 34.90, '2026-05-12 05:54:47'),
(117, 1084187, 'Lindas e Letais', 'Um thriller repleto de ação no qual cinco bailarinas, perdidas em uma floresta remota a caminho de uma competição de dança, encontram abrigo em uma pousada sinistra à beira da estrada, administrada por Devora Kasimer, e precisam usar seu treinamento de elite como arma para sobreviver.', '/3PdG3VE95F7fcawJrAfm9bdUvMy.jpg', '2026-03-13', '[10402,53,28,27]', 36.24, '2026-05-12 05:54:47'),
(118, 238, 'O Poderoso Chefão', 'Em 1945, Don Corleone é o chefe de uma mafiosa família italiana de Nova York. Ele costuma apadrinhar várias pessoas, realizando importantes favores para elas, em troca de favores futuros. Com a chegada das drogas, as famílias começam uma disputa pelo promissor mercado. Quando Corleone se recusa a facilitar a entrada dos narcóticos na cidade, não oferecendo ajuda política e policial, sua família começa a sofrer atentados para que mudem de posição. É nessa complicada época que Michael, um herói de guerra nunca envolvido nos negócios da família, vê a necessidade de proteger o seu pai e tudo o que ele construiu ao longo dos anos.', '/oJagOzBu9Rdd9BrciseCm3U3MCU.jpg', '1972-03-14', '[18,80]', 39.59, '2026-05-12 05:54:47'),
(119, 27205, 'A Origem', 'Cobb é um ladrão habilidoso que comete espionagem corporativa infiltrando-se no subconsciente de seus alvos durante o estado de sono. Impedido de retornar para sua família, ele recebe a oportunidade de se redimir ao realizar uma tarefa aparentemente impossível: plantar uma ideia na mente do herdeiro de um império. Para realizar o crime perfeito, ele conta com a ajuda do parceiro Arthur, o discreto Eames e a arquiteta de sonhos Ariadne. Juntos, eles correm para que o inimigo não antecipe seus passos.', '/9e3Dz7aCANy5aRUQF745IlNloJ1.jpg', '2010-07-15', '[28,878,12]', 38.06, '2026-05-12 05:54:47'),
(120, 10693, 'Peter Pan', 'Deixando o conforto e segurança de seus lares, Wendy, Miguel e João seguem Peter Pan para um mundo mágico onde a infância dura para sempre, a Terra do Nunca. Mas logo as crianças descobrem que precisarão confrontar o terrível Capitão Gancho, um maquiavélico pirata que quer se livrar de uma vez por todas de Peter.', '/bcmbrRVVs0RxNczCFC57onjHmkJ.jpg', '1953-02-05', '[16,10751,12,14]', 35.21, '2026-05-12 05:54:47'),
(121, 1115544, 'Mike & Nick & Nick & Alice', 'Uma comédia de ação hilária e estilizada, para maiores de 18 anos, sobre dois gângsteres e a mulher que eles amam, tentando sobreviver à noite mais perigosa de suas vidas. Como se isso não bastasse, tem um ingrediente inusitado na mistura: uma máquina do tempo.', '/7F0jc75HrSkLVcvOXR2FXAIwuEv.jpg', '2026-03-14', '[35,878,80]', 33.60, '2026-05-12 05:54:47'),
(122, 1472951, 'Infiltrate', '', '/8Cw8GF9wG63kF8pRRXwOx2kXGt.jpg', '2026-04-10', '[28,53]', 17.24, '2026-05-12 05:55:03'),
(123, 9502, 'Kung Fu Panda', 'Po é um panda que trabalha na loja de macarrão da sua família e sonha em transformar-se em um mestre de kung fu. Seu sonho se torna realidade quando, inesperadamente, ele deve cumprir uma profecia antiga e estudar a arte marcial com seus ídolos, os Cinco Furiosos. Po precisa de toda a sabedoria, força e habilidade que conseguir reunir para proteger seu povo de um leopardo da neve malvado.', '/1YMs3zCt5kICK28RvVgDL1UUtkA.jpg', '2008-06-04', '[28,16,35,10751]', 17.17, '2026-05-12 05:55:04'),
(124, 49026, 'Batman: O Cavaleiro das Trevas Ressurge', 'Após ser culpado pela morte de Harvey Dent e passar de herói a vilão, Batman desaparece. As coisas mudam com a chegada de uma ladra misteriosa, a Mulher-Gato, e Bane, um terrorista mascarado, que fazem Batman abandonar seu exílio forçado.', '/j4z01cnbTCaVX69bik1612pSuH6.jpg', '2012-07-17', '[28,80,18,53]', 17.17, '2026-05-12 05:55:04'),
(125, 359410, 'Matador de Aluguel', 'Um ex lutador de UFC aceita um trabalho como segurança em uma taberna em Florida Keys, apenas para descobrir que este não é o paraíso que parecia ser.', '/h2xDLj6CtzItwQEFyBjIXh5z3QD.jpg', '2024-03-08', '[28,53,18]', 17.12, '2026-05-12 05:55:04'),
(126, 986056, 'Thunderbolts*', 'Depois de se verem presos em uma armadilha mortal, uma equipe não convencional de sete anti-heróis deve embarcar em uma missão perigosa que os forçará a confrontar os cantos mais sombrios de seus passados.', '/3cME244QKWg5mAvcsmthmtx7VR1.jpg', '2025-04-30', '[28,878,12]', 17.09, '2026-05-12 05:55:04'),
(127, 985939, 'A Queda', 'Becky e Hunter são duas amigas que buscam aventura e enfrentam grande alturas em suas escaladas. Depois de um grande drama vivido por elas, as duas decidem escalar uma remota torre de rádio abandonada com mais de 2000 pés de altura. Parecia a aventura perfeita para desligar a mente do trágico acontecimento que vivenciaram com o namorado de uma delas. Elas não contavam que ficariam presas e isoladas naquele lugar sem sinal de celular, sem energia e sem pessoas por perto.', '/ey5j9PzI1S0jsMPuN8H9ldrGzuX.jpg', '2022-08-11', '[53]', 17.05, '2026-05-12 05:55:04'),
(128, 1511057, 'A Colega Perfeita', 'Devon acabou de entrar na faculdade. Celeste é popular e confiante. Quando as duas resolvem morar juntas, a amizade se transforma em uma verdadeira guerra.', '/36zoDJG52EkHnMm60M9BdLw8Siv.jpg', '2026-04-13', '[35]', 17.02, '2026-05-12 05:55:04'),
(129, 637649, 'Infiltrado', 'Harry, conhecido apenas como H, é um homem misterioso que trabalha para uma empresa de carros-fortes e movimenta grandes quantias de dinheiro pela cidade de Los Angeles. Quando, ao impedir um assalto, ele surpreende a todos com suas habilidades de combate, suas verdadeiras intenções começam a ser questionadas e um plano maior é revelado.', '/rNz8wy63GAabztAUkO4xMGk3upx.jpg', '2021-04-22', '[53,80,18]', 16.98, '2026-05-12 05:55:04'),
(130, 467905, 'Manual Prático da Vingança Lucrativa', 'Deserdado desde o nascimento por sua família bilionária, Becket Redfellow está determinado a recuperar a fortuna que sempre acreditou ser sua por direito. Para isso, ele irá orquestrar uma série de \"acidentes\" engenhosamente planejados, até que não reste nenhum herdeiro de pé.', '/eyYbgERxVuWBhCeZZLNFlZVWLz2.jpg', '2026-02-19', '[35,53]', 16.92, '2026-05-12 05:55:04'),
(131, 664413, '365 Dias', 'Laura, a fim de salvar seu relacionamento, vai para a Sicília, onde conhece Massimo. Um homem perigoso, o chefe de uma família da máfia, que a sequestra e lhe dá 365 dias para amá-lo.', '/3b1uR8Jggt1hWgtBbp42Mt3cwWe.jpg', '2020-02-07', '[10749,18]', 16.91, '2026-05-12 05:55:04'),
(132, 912649, 'Venom: A Última Rodada', 'Eddie e Venom estão fugindo. Perseguidos pelos dois mundos, a dupla é forçada a tomar uma decisão devastadora que vai fechar as cortinas da última rodada de Venom e Eddie.', '/eZIIPjL7oGqfmF7Gw5ZnbDjH6yu.jpg', '2024-10-22', '[878,28,12]', 16.88, '2026-05-12 05:55:04'),
(133, 68721, 'Homem de Ferro 3', 'Depois de um inimigo reduzir o mundo de Tony Stark a destroços, o Homem de Ferro precisa aprender a confiar em seus instintos para proteger aqueles que ama, especialmente sua namorada, e lutar contra seu maior medo: o fracasso.', '/C7MZwRTjvEy7gkWcLJeBGZFE1w.jpg', '2013-04-18', '[28,12,878]', 16.78, '2026-05-12 05:55:04'),
(134, 1315303, 'O Primata', 'A universitária Lucy vai passar férias em casa com a família e aproveita a ausência do pai para organizar uma festa na piscina. Durante o evento, seu chimpanzé de estimação surge irreconhecível e agressivo, contaminado com raiva, forçando o grupo a buscar algum jeito de escapar da fúria do animal.', '/fJd3J9FwWTAI1EZsvaTHfZKKTPy.jpg', '2026-01-01', '[27,53]', 16.76, '2026-05-12 05:55:04'),
(135, 49051, 'O Hobbit: Uma Jornada Inesperada', 'Como a maioria dos hobbits, Bilbo Bolseiro leva uma vida tranquila até o dia em que recebe uma missão do mago Gandalf. Acompanhado por um grupo de anões, ele parte numa jornada até a Montanha Solitária para libertar o Reino de Erebor do dragão Smaug.', '/lZtmn2pLw1kgDYj4Ig4s3DYBQCD.jpg', '2012-12-12', '[12,14,28]', 16.76, '2026-05-12 05:55:05'),
(136, 767, 'Harry Potter e o Enigma do Príncipe', 'À medida que Lord Voldemort aumenta seu controle sobre o mundo Trouxa e bruxo, Hogwarts não é mais um local seguro. Harry suspeita que haja perigos dentro do castelo, mas Dumbledore está mais empenhado em prepará-lo para a batalha final que se aproxima rapidamente. Juntos, eles trabalham para encontrar a chave para desbloquear as defesas de Voldemort e, para esse fim, Dumbledore recruta seu velho amigo e colega Horácio Slughorn, que ele acredita possuir informações cruciais. Mesmo quando o confronto decisivo se aproxima, o romance floresce para Harry, Ron, Hermione e seus colegas de classe. O amor está no ar, mas o perigo está por vir e Hogwarts pode nunca mais ser a mesma.', '/hTQQ5l9mxA3Rob8PTyvrNNGuj6y.jpg', '2009-07-15', '[12,14]', 16.73, '2026-05-12 05:55:05'),
(137, 346, 'Os Sete Samurais', 'Um bando de bandidos aterroriza os habitantes de uma pequena cidade, saqueando-os periodicamente sem piedade. Para repelir estes ataques, os aldeões decidem contratar mercenários. Por fim, obtêm os serviços de 7 guerreiros, 7 samurais dispostos a defendê-los em troca apenas de abrigo e comida.', '/2f3Aw6GCzpn1qw56xq78dH0VBgn.jpg', '1954-04-26', '[28,18]', 16.73, '2026-05-12 05:55:05');
INSERT INTO `movies` (`id`, `tmdb_id`, `title`, `overview`, `poster_path`, `release_date`, `genre_ids`, `popularity`, `created_at`) VALUES
(138, 933260, 'A Substância', 'Uma estrela em declínio descobre uma substância misteriosa que lhe permite criar uma versão mais jovem e perfeita de si mesma. No entanto, o que parece ser uma solução milagrosa para recuperar sua glória logo se transforma em um pesadelo perturbador quando as consequências desta decisão começam a se manifestar de formas sombrias e irreversíveis.', '/vWeOgzlhnP1sS23H3rzctGHB9Nb.jpg', '2024-09-07', '[27,878]', 16.72, '2026-05-12 05:55:05'),
(139, 156022, 'O Protetor', 'O ex-agente secreto Robert McCall acredita que seu passado ficou para trás e tenta viver uma nova vida. Porém, quando ele conhece Teri, uma jovem que está em poder de uma quadrilha russa, ele simplesmente não consegue ignorá-la. Munido de suas extraordinárias habilidades, ele ressurge como um verdadeiro anjo vingador. Fora da aposentadoria e com um novo desejo de fazer justiça, McCall decide ajudar quem foi brutalizado e oprimido.', '/xTSOdJ0Ljs439lnKB7NsWlTibZN.jpg', '2014-09-24', '[53,28,80]', 16.72, '2026-05-12 05:55:05'),
(140, 271110, 'Capitão América: Guerra Civil', 'Depois do ataque de Ultron, os políticos decidem controlar os Vingadores, já que suas ações afetam toda a humanidade. A decisão coloca o Capitão América em rota de colisão com o Homem de Ferro.', '/dsvUR5aEVSkB1Sro7nT6Khqik71.jpg', '2016-04-27', '[12,28,878]', 16.72, '2026-05-12 05:55:05'),
(141, 561, 'Constantine', 'John Constantine (Keanu Reeves) é um experiente ocultista e exorcista, que literalmente chegou ao inferno. Juntamente com Angela Dodson (Rachel Weisz), uma policial cética, ele investiga o misterioso assassinato da irmã gêmea dela, Isabel. As investigações levam a dupla a um mundo sombrio, em que precisam lidar com demônios e anjos malvados.', '/dd4uzgUAbBIiRW7dcY0AcgSWohJ.jpg', '2005-02-08', '[14,28,27]', 16.67, '2026-05-12 05:55:05'),
(182, 1215106, 'หมู่บ้านโคกะโหลก', '', '/pRWBabtsYvqpPmxNYcejIUe6lc3.jpg', '2025-11-06', '[35,27]', 14.85, '2026-05-12 05:58:10'),
(183, 101, 'O Profissional', 'Mathilda tem apenas 12 anos de idade mas já conhece o lado obscuro da vida: seu pai abusivo guarda drogas para policiais corruptos e a mãe a negligencia. O vizinho Léon gosta de cuidar de plantas, mas é um assassino de aluguel para o gângster Tony. Quando sua família é assassinada por um agente antidrogas desonesto, Mathilda se une a um relutante Léon para aprender o negócio mortal e vingar a morte da família.', '/lNyuX5XibtzRImuhACGy42jHXIs.jpg', '1994-09-14', '[80,18,28]', 21.18, '2026-05-12 05:58:10'),
(184, 58, 'Piratas do Caribe: O Baú da Morte', 'Will e Elizabeth estão prestes a se casar quando o lendário pirata Davy Jones, comandante do invencível navio assombrado O Holandês Voador, aparece para cobrar uma dívida do capitão Jack Sparrow, amigo do casal. A única chance de Sparrow se livrar de uma maldição de Jones é encontrando o baú da morte.', '/yvD1G41HwHgj8afCjmfGbyRmBBR.jpg', '2006-07-06', '[12,14,28]', 18.81, '2026-05-12 05:58:11'),
(185, 1480387, 'undertone', 'A apresentadora de um popular podcast paranormal passa a ser assombrada por gravações aterrorizantes misteriosamente enviadas a ela.', '/2PFgFMnrdCPXWiZl1PUvky7Mo9D.jpg', '2026-03-12', '[27,9648]', 20.48, '2026-05-12 05:58:11'),
(186, 585, 'Monstros S.A.', 'O astro do susto, Sulley, e seu falante assistente, Mike, trabalham na Monstros S.A., a maior fábrica de processamento de gritos da cidade de Monstrópolis. A principal fonte de energia do mundo dos monstros provém da coleta dos gritos das crianças humanas. Os monstros acreditam que as crianças são tóxicas, e entram em pânico quando uma menininha invade seu mundo. Sulley e Mike fazem de tudo para levar a garota de volta para casa, mas enfrentam desafios monstruosos e algumas situações hilárias em suas atrapalhadas aventuras.', '/5p6cdAeUevsLOX0oI1T4JIul4QO.jpg', '2001-11-01', '[16,35,10751]', 20.43, '2026-05-12 05:58:11'),
(187, 389, '12 Homens e uma Sentença', 'Um jovem porto-riquenho é acusado do brutal crime de ter matado o próprio pai. Quando ele vai a julgamento, doze jurados se reúnem para decidir a sentença, levando em conta que o réu deve ser considerado inocente até que se prove o contrário. Onze dos jurados têm plena certeza de que ele é culpado, e votam pela condenação, mas um jurado acha que é melhor investigar mais para que a sentença seja correta. Para isso ele terá que enfrentar diferentes interpretações dos fatos, e a má vontade dos outros jurados, que só querem ir logo para suas casas.', '/aiHIhV8c45FzIlbqYlswrrNyQD6.jpg', '1957-04-10', '[18]', 20.81, '2026-05-12 05:58:11'),
(188, 290098, 'A Criada', 'Coreia do Sul, anos 1930. Durante a ocupação japonesa, a jovem Sookee é contratada para trabalhar para uma herdeira nipônica, Hideko, que leva uma vida isolada ao lado do tio autoritário. Só que Sookee guarda um segredo: ela e um vigarista planejam desposar a herdeira, roubar sua fortuna e trancafiá-la em um sanatório. Tudo corre bem com o plano, até que Sookee aos poucos começa a compreender as motivações de Hideko.', '/q6ngYthHXCvA2ZubO4FHTFNRrmc.jpg', '2016-06-01', '[53,18,10749]', 19.73, '2026-05-12 05:58:11'),
(189, 414906, 'Batman', 'Em seu segundo ano de combate ao crime, Batman descobre corrupção em Gotham City que se conecta à sua própria família enquanto enfrenta um serial killer conhecido como Charada.', '/wd7b4Nv9QBHDTIjc2m7sr0IUMoh.jpg', '2022-03-01', '[80,9648,53]', 20.30, '2026-05-12 05:58:11'),
(190, 673, 'Harry Potter e o Prisioneiro de Azkaban', 'É o início do terceiro ano na escola de magia e bruxaria de Hogwarts. Harry, Ron e Hermione têm muito o que aprender. Mas uma ameaça ronda a escola e ela se chama Sirius Black. Após doze anos encarcerado na prisão de Azkaban, ele consegue escapar e volta para vingar seu mestre, Lord Voldemort. Para piorar, os Dementores, guardas supostamente enviados para proteger Hogwarts e seguir os passos de Black, parecem ser ameaças ainda mais perigosas.', '/1HdMUghqlgOIvbsU9ZtO40IPRzl.jpg', '2004-05-31', '[12,14]', 20.02, '2026-05-12 05:58:11'),
(191, 10681, 'WALL-E', 'No ano 2800, num planeta Terra devastado e sem vida, depois de centenas de anos solitários a fazer aquilo para que foi construído - limpar o planeta de lixo - o pequeno robô WALL-E descobre uma nova missão na sua vida quando conhece uma moderna e brilhante robô exploradora chamada EVE. Os dois vão viajar pela galáxia e viver uma aventura emocionante e inesquecível.', '/qNiwJPVCO4cgiM8LVtxwPV2HxHS.jpg', '2008-06-22', '[16,10751,878]', 22.21, '2026-05-12 05:58:11'),
(192, 12, 'Procurando Nemo', 'Nemo, um jovem peixe-palhaço aventureiro, é inesperadamente levado de sua casa na Grande Barreira de Corais para o aquário do consultório de um dentista. Cabe ao seu preocupado pai Marlin e à simpática mas esquecida peixe Dory trazer Nemo para casa - encontrando tubarões vegetarianos, tartarugas surfistas, medusas hipnóticas, gaivotas esfomeadas e muito mais pelo caminho.', '/djbivExXSZb0sTO8uYaaQC5vMRM.jpg', '2003-05-30', '[16,10751,12]', 18.50, '2026-05-12 05:58:11'),
(193, 623983, 'Michael Jackson: Chase the Truth', 'Michael Jackson: Chase the Truth é um documentário de 2019 da Entertain Me Productions. O filme defende o cantor Michael Jackson contra as acusações de abuso sexual infantil feitas por Wade Robson e James Safechuck no documentário de 2019 Leaving Neverland.', '/v230avGQGCKTe4RJ13cLaAwFQOT.jpg', '2019-08-13', '[99]', 17.09, '2026-05-12 05:58:11'),
(194, 564, 'A Múmia', 'Em 1926, um grupo de arqueólogos descobre uma tumba na cidade perdida de Hamunaptra. Dentro da tumba é encontrado o corpo de Imhotep, o sacerdote do Faraó Seti, que foi mumificado vivo além de ter recebido a mais terrível das maldições por ter dormido com a amante do faraó e, movido por ciúme doentio e amor, ter matado o Faraó. No entanto, quando um dos membros da expedição lê um manuscrito que foi encontrado pelo grupo e traz Imhotep de volta vida, ele ressurge cheio de ódio e só pensa em reencontrar sua amada e destruir todos que cruzem o seu caminho, trazendo consigo as dez pragas do Egito.', '/kyLGWOQT17uOJwYIn0sgj00vVPo.jpg', '1999-04-16', '[12,28,14]', 20.61, '2026-05-12 05:58:11'),
(195, 574475, 'Premonição 6: Laços de Sangue', 'Atormentada por um pesadelo violento recorrente, a estudante universitária Stefanie volta para casa para encontrar a única pessoa que pode quebrar o ciclo e salvar sua família do destino horrível que inevitavelmente os aguarda.', '/x3J781PsdMrjenzQKM5eJXqK5Nd.jpg', '2025-05-14', '[27,9648]', 18.87, '2026-05-12 05:58:12'),
(196, 22, 'Piratas do Caribe: A Maldição do Pérola Negra', 'O pirata Jack Sparrow tem seu navio saqueado e roubado pelo capitão Barbossa e sua tripulação. Com o navio de Sparrow, Barbossa invade a cidade de Port Royal, levando consigo Elizabeth Swann, filha do governador. Para recuperar sua embarcação, Sparrow recebe a ajuda de Will Turner, um grande amigo de Elizabeth. Eles desbravam os mares em direção à misteriosa Ilha da Morte, tentando impedir que os piratas-esqueleto derramem o sangue de Elizabeth para desfazer a maldição que os assola.', '/9Xcg7Ar4ketv4rl8yeK32yp9zQA.jpg', '2003-07-09', '[12,14,28]', 18.51, '2026-05-12 05:58:12'),
(197, 652, 'Tróia', 'Quando Páris, o príncipe de Troia, se apaixona por Helena, rainha de Esparta, o rei inicia uma guerra de anos entre os dois reinos. Para vencer, Esparta conta com Aquiles, um guerreiro lendário que comanda um exército próprio.', '/iKp2NxUkqPVSPN2FdXUn9gxj4Nn.jpg', '2004-05-13', '[10752,28,36]', 19.41, '2026-05-12 05:58:12'),
(198, 244786, 'Whiplash: Em Busca da Perfeição', 'Andrew sonha em ser o melhor baterista de sua geração. Ele chama a atenção do impiedoso mestre do jazz Terence Fletcher, que ultrapassa os limites e transforma seu sonho em uma obsessão, colocando em risco a saúde física e mental do jovem músico.', '/z693uKD7j3zcdX0zVMQPIA3cSZf.jpg', '2014-10-10', '[18,10402,53]', 20.72, '2026-05-12 05:58:12'),
(199, 1197306, 'Resgate Implacável', 'Ele quer viver uma vida simples e ser um bom pai para sua filha. Mas quando a filha adolescente de seu chefe, Jenny, desaparece, ele é chamado para reempregar as habilidades que o tornaram uma figura lendária nas operações secretas.', '/1w01rEQRYvIoSs5Is9cQDJhiUel.jpg', '2025-03-26', '[28,80,53]', 17.31, '2026-05-12 05:58:12'),
(200, 18240, 'A Proposta', 'Margaret Tate é uma poderosa editora de livros, que se vê em apuros ao ser comunicada de sua deportação para o país-natal, o Canadá. Para evitar que isto ocorra ela declara estar noiva de Andrew Paxton, seu assistente. Perseguido por Margaret há anos, ele aceita participar da farsa mas impõe algumas condições.', '/uIhags0jXoe78JJjCDZbByciesQ.jpg', '2009-06-02', '[35,10749,18]', 19.85, '2026-05-12 05:58:12'),
(201, 11324, 'Ilha do Medo', 'No verão de 1954, os agentes judiciais Teddy Daniels (DiCaprio) e Chuck Aule (Ruffalo) foram designados para uma ilha remota do porto de Boston para investigar o desaparecimento de uma perigosa assassina (Mortimer) que estava reclusa no hospital psiquiátrico Ashecliffe, um centro penitenciário para criminosos perturbados dirigido pelo sinistro médico John Cawley. (Kingsley). Logo eles descobrem que o centro guarda muitos segredos e que a ilha esconde algo mais perigoso que os pacientes.', '/erl801HYIodoIBGZeFk0GTwCUBh.jpg', '2010-02-14', '[18,53,9648]', 19.08, '2026-05-12 05:58:12'),
(204, 980431, 'A Lenda de Aang: O Último Mestre do Ar', 'O Avatar Aang, o último mestre do ar do mundo, toma conhecimento de um poder antigo que poderia salvar sua cultura da extinção. Com a ajuda de seus amigos, ele embarca em uma busca global para encontrá-lo antes que caia em mãos erradas e ameace destruir a paz que eles sacrificaram tudo para alcançar.', '/mTdadPqjkcjOphSsKXLiW2fgLMm.jpg', '2026-10-09', '[16,28,12,14]', 112.02, '2026-05-12 05:58:52'),
(205, 1241752, 'Rita', '', '/grIFQLXXwQmjvYYfXVXCgGTMUWw.jpg', '2024-03-22', '[18]', 118.07, '2026-05-12 05:58:52'),
(206, 1510745, 'POV: Presença Oculta', 'O que começou como uma chamada de rotina vira um pesadelo quando dois policiais se envolvem em um acidente fatal. Bryce, desesperado para proteger seu emprego e sua família, convence seu parceiro a destruir todos os registros para esconder a verdade. Mas conforme a madrugada avança, eles percebem que as câmeras não eram as únicas testemunhas e que algo sobrenatural acompanhava cada movimento deles naquela noite.', '/fC4GSEiDu2ONAOjT3VhKdAOR2UI.jpg', '2026-03-12', '[27]', 98.95, '2026-05-12 05:58:52'),
(207, 1038918, '美女奉行 おんな牢秘抄II', '', '/i3Ouy0rMUHyKeHZV3PYl106OSwe.jpg', '1995-09-21', '[18,36]', 84.02, '2026-05-12 05:58:52'),
(208, 1290821, 'Missão Refúgio', 'Um ex-assassino de aluguel, agora um homem recluso numa ilha costeira remota, salva uma garota de uma tempestade terrível, colocando os dois na mira do perigo. Forçado a sair da aposentadoria e do isolamento, o homem é obrigado a enfrentar seu passado perigoso para proteger a menina enquanto tenta sobreviver uma jornada tensa repleta de perigos e redenção.', '/hSvhZRkbYD9crC4nqy8uCk9EdFH.jpg', '2026-01-28', '[28,80,53]', 101.07, '2026-05-12 05:58:52'),
(209, 1311031, 'Demon Slayer: Kimetsu no Yaiba Castelo Infinito', 'Enquanto os membros dos caçadores e os Hashira participavam de um rigoroso programa de fortalecimento coletivo, conhecido como Treinamento dos Hashira, em preparação para a batalha final contra os demônios, Muzan Kibutsuji aparece na Mansão Ubuyashiki. Com a vida do líder da organização em risco, Tanjiro e os Hashira correm até o quartel-general, mas acabam sendo lançados, pelas mãos de Muzan, em uma queda profunda rumo a um espaço misterioso para um confronto final, o Castelo Infinito.', '/c55sXCaQBj3vuHqZe62tv90xCQS.jpg', '2025-07-18', '[16,28,14]', 97.64, '2026-05-12 05:58:52'),
(210, 1084242, 'Zootopia 2', 'Os detetives Judy Hopps e Nick Wilde se encontram na trilha sinuosa de um réptil misterioso que chega a Zootopia e vira a metrópole dos mamíferos de cabeça para baixo.', '/v8sjoZynhlyAT4pYdTI8m7FFHq9.jpg', '2025-11-26', '[12,16,35,10751,9648]', 93.97, '2026-05-12 05:58:52'),
(211, 1325734, 'O Drama', 'Profundamente apaixonados e em meio aos preparativos finais para o grande dia do casamento, o casal tem sua felicidade ameaçada quando vêm à tona segredos que jamais poderiam imaginar.', '/tM3hbeEwJZdQAjwwt5UjFn638AY.jpg', '2026-03-26', '[10749,35,18]', 94.35, '2026-05-12 05:58:53'),
(212, 1426822, 'O Monstro da Ilha', 'Um grupo de caçadores viaja até uma misteriosa ilha para procurar por uma criatura lendária, mas descobrem que estão sendo usados como isca.', '/mvGem9E8avZEg33F9csGHGBT7kM.jpg', '2025-02-03', '[27,28]', 99.54, '2026-05-12 05:58:53'),
(213, 460465, 'Mortal Kombat', 'O lutador de MMA Cole Young deve treinar para liberar seu verdadeiro poder para unir-se aos maiores campeões mundiais contra inimigos da Exoterra em uma batalha decisiva pelo universo.', '/4nW5X9iBrMlHMDcTsEOQWXKu3TZ.jpg', '2021-04-07', '[28,14,12]', 103.57, '2026-05-12 05:58:53'),
(214, 1414413, 'Brothers Under Fire', '', '/e5EKqk9V7N3w0WvYFhl6wSVrMp0.jpg', '2026-04-15', '[28,53,9648,18]', 82.60, '2026-05-12 05:58:53'),
(215, 1242898, 'Predador: Terras Selvagens', 'No futuro, em um planeta remoto, um jovem Predador, rejeitado por seu clã, encontra em Thia uma aliada improvável e embarca em uma jornada traiçoeira em busca do adversário supremo.', '/f3yLlUrJDdDL8d4nxywyotN45SL.jpg', '2025-11-05', '[28,878,12]', 85.06, '2026-05-12 05:58:53'),
(216, 1235192, 'Wormtown', 'Quando um culto que adora parasitas que alteram a mente toma conta de uma pequena cidade, um trio de mulheres enrustidas é arrastado para uma luta pela sobrevivência e vingança.', '/lE10ww38b7XA5LIagIsVQj9a8Hn.jpg', '2025-09-27', '[878,27,12]', 90.82, '2026-05-12 05:58:53'),
(217, 755898, 'A Guerra dos Mundos', 'Will Radford é um renomado analista de cibersegurança do Departamento de Segurança Interna dos Estados Unidos, encarregado de rastrear possíveis ameaças à segurança nacional por meio de um programa de vigilância em massa. No entanto, um ataque inesperado por uma entidade desconhecida o leva a suspeitar que o governo esteja escondendo algo dele… e do restante do mundo.', '/yY5CbfXBxsPvYi0TzmaCP7uunnn.jpg', '2025-07-29', '[878,53]', 76.40, '2026-05-12 05:58:54'),
(218, 1173559, 'Insidious Inferno', '', '/8kljUAovBatZRYp2ye2RZr239hU.jpg', '2024-11-29', '[27]', 68.69, '2026-05-12 05:58:54'),
(219, 1171145, 'Caminhos do Crime', 'Um ladrão enigmático realiza assaltos de alto risco ao longo da icônica rodovia 101. Quando ele mira o golpe de sua vida — na esperança de que este seja seu último trabalho —, seu caminho cruza com o de uma corretora de seguros desiludida, forçando os dois a colaborar. Determinado a desvendar o caso, um detetive implacável se aproxima da operação.', '/3u8Pr8WF9hqMptlnuYL52YXSs8F.jpg', '2026-02-11', '[80,53]', 67.58, '2026-05-12 05:58:54'),
(220, 1419406, 'A Sombra do Perigo', 'Um policial aposentado, especialista em rastreamento, é convocado de volta à ativa em Macau para desmantelar uma gangue de ladrões de alta tecnologia, colocando suas táticas tradicionais contra a tecnologia avançada, num jogo de gato e rato com uma equipe de jovens detetives de elite.', '/wqdHjQ1UpfQgS9jN9So5PLNTwoX.jpg', '2025-08-16', '[28,80,18,53]', 69.01, '2026-05-12 05:58:54'),
(221, 1579, 'Apocalypto', 'Jaguar Paw levava uma vida tranquila, que foi interrompida devido à uma invasão. Os governantes de um império maia em declínio acreditavam que a chave para a prosperidade seria construir mais templos e realizar mais sacrifícios humanos. Jaguar é capturado para ser um destes sacrifícios, mas consegue escapar por acaso. Agora, guiado apenas pelo amor que sente por sua esposa e pela filha, ele realiza uma corrida desesperada para chegar em casa e salvar sua família.', '/zkt0AvCCbx3rOUkqqYrCZH4jeQo.jpg', '2006-12-07', '[28,18,36]', 66.89, '2026-05-12 05:58:54'),
(222, 1270125, 'Monstro a Bordo', 'O Dr. Sigh tenta trazer uma misteriosa criatura de uma terra distante para a Alemanha. Mas após o avião ser atingido por uma turbulência, a criatura desperta e começa a atacar os passageiros.', '/fGKaYbPMx4ovrx2DlLS4CUarqOS.jpg', '2024-11-07', '[27,35]', 28.77, '2026-05-12 06:02:00'),
(223, 1214931, 'Nuremberg', 'Um psiquiatra dos Estados Unidos é designado para examinar 22 oficiais nazistas que aguardam julgamento por crimes de guerra. À medida que ele se aproxima de um de seus pacientes e tenta desvendar a essência do mal, ele se vê envolvido em uma jornada sem volta.', '/saPapyxafNZxIPqYa2xm4QkaxpE.jpg', '2025-11-06', '[36,18]', 28.19, '2026-05-12 06:02:00'),
(224, 950396, 'Entre Montanhas', 'Dois agentes altamente treinados se aproximam à distância após serem enviados para proteger lados opostos de um desfiladeiro misterioso. Quando um mal emerge, eles precisam trabalhar juntos para sobreviver ao que está lá dentro.', '/7zL6RxMPmpPSdU5OTdVC4dtiKcr.jpg', '2025-02-13', '[10749,878,53]', 30.49, '2026-05-12 06:02:00'),
(225, 1651233, 'O Genro', 'Depois de seguir um caminho difícil, José Sánchez se torna um temido operador político. Mas, desta vez, seu bigode marcante e a língua afiada não serão suficientes.', '/pS1hk20bUfGZ4tFf9r0Ws0gGPoZ.jpg', '2026-04-18', '[35,18]', 28.14, '2026-05-12 06:02:00'),
(226, 858024, 'Hamnet: A Vida Antes de Hamlet', 'Um dos mais importantes escritores do cânone ocidental, William Shakespeare vive uma tragédia ao lado de sua esposa Agnes quando o casal perde o filho de 11 anos para uma das várias pragas que assolaram o século XVI. Hamnet era o nome do menino. Explorando os temas da perda e da morte, o filme acompanha a rotina e o dia a dia de uma família, as alegrias e as tristezas de viver numa pequena vila na Inglaterra do passado e a história de amor poderosa que inspirou a criação da peça Hamlet.', '/njatIGrIlZCxB88UUBC2xgmfCNE.jpg', '2025-11-26', '[18,10749,36]', 25.24, '2026-05-12 06:02:00'),
(227, 1010755, 'Os Estranhos: Capítulo Final', 'Maya enfrenta os assassinos mascarados uma última vez em um acerto de contas brutal e cíclico de sobrevivência e vingança.', '/jYaPXOzUFVlNIn5Cgn1dyVRYpRN.jpg', '2026-02-05', '[27,53]', 30.36, '2026-05-12 06:02:00'),
(228, 533535, 'Deadpool & Wolverine', 'Um apático Wade Wilson trabalha duro na vida civil. Seus dias como mercenário moralmente flexível, Deadpool, ficaram para trás. Quando seu planeta enfrenta uma ameaça, Wade deve relutantemente vestir-se novamente com um ainda mais relutante... relutante? Mais relutante? Ele deve convencer um Wolverine relutante em... Porra. As sinopses são tão estúpidas.', '/53YWSo75mSaw1vd2YEeX5kwkRos.jpg', '2024-07-24', '[28,35,878]', 31.47, '2026-05-12 06:02:01'),
(229, 120, 'O Senhor dos Anéis: A Sociedade do Anel', 'Após herdar um anel de seu tio, o hobbit Frodo participa da missão de salvar a Terra-Média do perverso Sauron. Ele precisa conduzir o Um Anel até a Montanha da Perdição e destruí-lo para sempre e, para isso, conta com a aliança de oito bravos companheiros contando com um mago, três hobbits, um elfo, um anão e dois homens.', '/tlvsNCwWEIgwAM23aNzTmMIcPEZ.jpg', '2001-12-18', '[12,14,28]', 30.58, '2026-05-12 06:02:01'),
(230, 567609, 'Casamento Sangrento', 'Grace acaba de se casar com o herdeiro milionário de uma família especializada em jogos de tabuleiro. Antes de realmente integrar a família, no entanto, ela é obrigada a participar de uma tradição familiar: um jogo de esconde-esconde pela mansão dos Le Domas. Aos poucos, Grace percebe que a brincadeira inocente é na verdade uma caçada sangrenta contra a recém-casada, em que todas as armas e golpes são permitidos para assassiná-la. A jovem terá a difícil missão de sobreviver aos ataques até o amanhecer.', '/k5dJuAdjv1wCq2Vzj1GZfwGmLoU.jpg', '2019-08-21', '[27,35]', 29.98, '2026-05-12 06:02:01'),
(231, 1336770, 'വാഴ II', '', '/1yLZ7kExd0UGGbaZW4LxmYD4OIf.jpg', '2026-04-02', '[35,18]', 35.48, '2026-05-12 06:02:01'),
(232, 1383519, 'Playa de lobos', '', '/kvUDtcqsDX9uqnHd74h7doAzlKd.jpg', '2025-10-24', '[35,53]', 30.28, '2026-05-12 06:02:01'),
(233, 361743, 'Top Gun: Maverick', 'Depois de mais de 30 anos de serviço como um dos principais aviadores da Marinha, Pete \"Maverick\" Mitchell está de volta, rompendo os limites como um piloto de testes corajoso. No mundo contemporâneo das guerras tecnológicas, Maverick enfrenta drones e prova que o fator humano ainda é essencial.', '/kPbuLGVSJHATkW9fX9L3h1wM0Pa.jpg', '2022-05-21', '[28,18]', 31.52, '2026-05-12 06:02:01'),
(234, 214756, 'Ted 2', 'O urso de pelúcia Ted casa-se com Tami-Lynn. O casal pretende ter um bebê, mas para terem direito à inseminação artificial, Ted tem que provar na justiça que é um ser humano. Para alcançar o seu sonho, ele conta com a ajuda da advogada Samantha e do seu grande amigo John.', '/kblxjPVIXaIQ7iHo5b2LaBOEllD.jpg', '2015-06-25', '[35,14]', 29.24, '2026-05-12 06:02:01'),
(235, 10729, 'Não Tenho Troco', 'Grimm é um assaltante que, vestido de palhaço, assalta um banco em companhia da sua namorada Phyllis e de um amigo, Loomis, que o ajudaram na operação fingindo serem clientes do banco. O trio planeja sair do país, mas vários contratempos podem prejudicar os planos.', '/n6k0hobXzb22LhuZiiLuiJVro9.jpg', '1990-07-13', '[35,80]', 28.38, '2026-05-12 06:02:01'),
(236, 1446616, 'Você ou Eu?', 'O romance entre um rapper de classe baixa e uma influenciadora rica é colocado à prova quando os dois ficam presos com um crocodilo violento.', '/nUPnA0I1MTaZRVCsUQc5DS5JA8W.jpg', '2026-02-11', '[53,10749]', 28.19, '2026-05-12 06:02:01'),
(237, 1160946, 'Animalicious', '', '/hsvUSlIqJyGXS3GpWR3LZiipWcs.jpg', '1999-01-01', '[99,10770]', 26.41, '2026-05-12 06:02:01'),
(238, 1539104, 'JUJUTSU KAISEN: Execução', 'Yuji Itadori, acompanhado por seus colegas de classe e outros feiticeiros jujutsu de alto nível, entra na briga em um confronto sem precedentes de maldições: o Incidente de Shibuya. No rescaldo, dez colônias em todo o Japão são transformadas em antros de maldições em um plano orquestrado por Noritoshi Kamo, o feiticeiro mais perverso da história.', '/sa646tMUGfCdOvwnHvzqycxzSoB.jpg', '2025-11-07', '[16,28,14]', 29.65, '2026-05-12 06:02:01'),
(239, 807, 'Seven - Os Sete Crimes Capitais', 'Quando, a ponto de se aposentar, o detetive William Somerset aborda o último caso com a ajuda do recém-transferido David Mills, eles descobrem uma série de assassinatos. Logo percebem que estão lidando com um assassino que tem como alvo pessoas que ele acredita representar os sete pecados capitais.', '/dZXYPSEaXCeigR2GEuZoukNmLTf.jpg', '1995-09-22', '[80,9648,53]', 29.88, '2026-05-12 06:02:02'),
(240, 1430077, 'Hokum: O Pesadelo da Bruxa', 'O escritor solitário Ohm Bauman refugia-se em um hotel isolado para cumprir o último desejo de seus pais. A despedida silenciosa transforma-se em pesadelo quando histórias sobre uma antiga bruxa que assombra a suíte de lua de mel passam a invadir seus sonhos e sua mente. Entre visões perturbadoras e um desaparecimento chocante, Ohm é levado a um confronto aterrorizante com as forças que cercam o local e com os cantos mais sombrios de seu próprio passado.', '/b9fyqIgQKW0VK1eKTsKKa5ijHOn.jpg', '2026-04-29', '[27]', 23.61, '2026-05-12 06:02:02'),
(241, 1214361, 'Bad Men Must Bleed', '', '/cMJCAyK0m8gVGEzuwrlPqOPNc5r.jpg', '2026-03-12', '[37,80,53]', 23.90, '2026-05-12 06:02:02'),
(262, 524047, 'Destruição Final: O Último Refúgio', 'Quando cientistas descobrem que um cometa atingirá a Terra em poucos dias e provavelmente causará a extinção da humanidade, uma família tenta cruzar o país para chegar a sua única esperança de sobrevivência: um grupo de abrigos subterrâneos em Greenland.', '/65p4M9Cdkv6YkHMmoTDMxQ8Gur8.jpg', '2020-07-29', '[53,12,28,878]', 14.20, '2026-05-12 06:04:37'),
(263, 353069, 'O Maior Amor do Mundo', 'Histórias associadas à maternidade se cruzam. Sandy é uma mãe solteira com dois filhos, Bradley é um pai solteiro com uma filha adolescente, Jesse tem uma história complicada com a sua mãe, Kristin nunca conheceu a sua mãe biológica e Miranda é uma escritora de sucesso que abre mão de ter filhos para se dedicar à carreira.', '/6tlIPSj1S74DlFkjhXK5yaXx1jp.jpg', '2016-04-28', '[35,18,10749]', 14.00, '2026-05-12 06:04:37'),
(264, 1930, 'O Espetacular Homem-Aranha', 'Peter Parker está tentando saber mais sobre sua origem. Ele encontra uma pasta que pertenceu ao seu pai e quer descobrir por que seus pais desapareceram. Sua busca o leva a Oscorp e ao dr. Curt Connors, que tem como alterego o letal Lagarto.', '/gxSsFBCFuDhVQMCuIDoZcmHOqlY.jpg', '2012-06-23', '[28,12,878]', 14.23, '2026-05-12 06:04:38'),
(265, 205596, 'O Jogo da Imitação', 'Em 1939, a recém-criada agência de inteligência britânica MI6 recruta Alan Turing, um aluno da Universidade de Cambridge, para entender códigos nazistas, incluindo o \"Enigma\", que criptógrafos acreditavam ser inquebrável. A equipe de Turing, incluindo Joan Clarke, analisa as mensagens de \"Enigma\", enquanto ele constrói uma máquina para decifrá-las.', '/pNa7vGKv04X2jnKifxLCTHPmWUT.jpg', '2014-11-14', '[36,18,53,10752]', 14.62, '2026-05-12 06:04:38'),
(266, 287649, 'Scarlet Innocence', 'Há 8 anos, professor da Universidade de Hak-Kyu mudou-se para uma pequena cidade por causa de um escândalo. Ele trabalhou como instrutor de literatura em um centro de cultura. Ele se apaixonou por uma mulher jovem, Deok-Yi, que trabalhava em um antigo parque de diversões. Uma vez, Hak-Kyu foi reintegrado na universidade, ele deixou a cidade para Seul e deixou para trás Deok-Yi.  Agora, Hak-Kyu é um escritor popular, mas sua Cheong se culpa pela sua mãe cometer suicídio. Hak-Kyu também está perdendo sua visão para uma doença. Ele é apenas capaz de ver. Neste momento, Se-Jung se muda para a porta ao lado. Ninguém percebe Se-Jung é realmente Deok-Yi, a mulher que Hak-Kyu traiu há 8 anos.', '/trvtnsNZjHwvB97RLQ3Nc5oncti.jpg', '2014-10-02', '[53,18,10749]', 13.11, '2026-05-12 06:04:38'),
(267, 313534, 'Nova Dubai', '', '/6muPGyLRhu7tiGnLt5msDqBVknR.jpg', '2014-10-23', '[18]', 13.70, '2026-05-12 06:04:38'),
(268, 1083612, 'Uma História de Sobrevivência', 'A notável história real de sobrevivência de um menino judeu que se esconde e é caçado nas florestas da Europa Oriental ocupada pelos nazistas.', '/pfW4P8yF9OEyg1VUKTr39NW6KXi.jpg', '2023-09-19', '[18,10752,36]', 13.25, '2026-05-12 06:04:38'),
(269, 296096, 'Como Eu Era Antes de Você', 'Will é um garoto rico e bem-sucedido, até sofrer um grave acidente que o deixa preso a uma cadeira de rodas. Ele está profundamente depressivo e contrata uma garota do campo para cuidar dele. Ela sempre levou uma vida modesta, com dificuldades financeiras e problemas no trabalho, mas está disposta a provar para Will que ainda existem razões para viver.', '/1a60KPNTC4JKYphNQveAB37Lyif.jpg', '2016-06-01', '[18,10749]', 13.16, '2026-05-12 06:04:39'),
(270, 286217, 'Perdido em Marte', 'O astronauta Mark Watney é enviado a uma missão em Marte. Após uma severa tempestade ele é dado como morto, abandonado pelos colegas e acorda sozinho no misterioso planeta com escassos suprimentos, sem saber como reencontrar os companheiros ou retornar à Terra.', '/fG3S4zdgnsaF77tJGK3rA9tHBu4.jpg', '2015-09-30', '[878,18,12]', 15.32, '2026-05-12 06:04:39'),
(271, 412117, 'Pets: A Vida Secreta dos Bichos 2', 'Max se vê enganado por Katie no primeiro trailer da animação e acaba dentro de uma clínica veterinária onde os pets não parecem nada normais. Nesta sequência, o protagonista ainda terá que se acostumar com um recém-chegado à família.', '/lLfEOjuzNK7c8c0PpQL3UDZRde0.jpg', '2019-05-24', '[10751,35,12,16]', 12.27, '2026-05-12 06:04:39'),
(272, 1144107, 'A Lenda de Hei 2', 'O filme conta a história de uma “nova missão” do Monster Hall. Diante de uma série de mistérios, Xiaohei e sua irmã mais velha, Luye, embarcam em uma nova aventura para descobrir a verdade.', '/rmdy6AVOlFEne4IM5Jj0WBOhCBP.jpg', '2025-07-18', '[16,14,28,12]', 12.71, '2026-05-12 06:04:39'),
(273, 38365, 'Gente Grande', 'A morte do treinador de basquete da infância de velhos amigos os reúne no mesmo lugar que celebraram um campeonato anos atrás. Os amigos, acompanhados de suas esposas e filhos, descobrem que idade não significa o mesmo que maturidade.', '/ppU2xJnlKdW3F01AtC9wMuXRZCg.jpg', '2010-06-24', '[35]', 13.86, '2026-05-12 06:04:39'),
(274, 19994, 'Garota Infernal', 'Ao ser possuída por um demônio, a estudante Jennifer se torna muito brava com os rapazes que nunca a deram uma chance. Enquanto a maldosa Jennifer satisfaz seu apetite com carne humana de meninos da escola, sua amiga nerd Needy descobre o que está acontecendo e promete colocar um fim na carnificina.', '/lIHXfHgVPDP0r5tKuysqpNkQQmV.jpg', '2009-09-18', '[27,35]', 13.99, '2026-05-12 06:04:39'),
(275, 1213898, 'Na Fronteira 2', 'Três soldados idealistas do exército, marinha e força aérea indianos enfrentam condições de combate extenuantes neste filme ambientado durante a Guerra Índia-Paquistão de 1971.', '/7I8fw5ofYNcTgjcFmEInUWr8YOo.jpg', '2026-01-23', '[28,18,10752]', 11.97, '2026-05-12 06:04:39'),
(276, 284052, 'Doutor Estranho', 'Após sua carreira ser destruída, um brilhante, porém arrogante, cirurgião ganha uma nova chance em sua vida quando um feiticeiro o treina para se tornar o Mago Supremo.', '/pb4clPWRJ5AKlSFu1HrrHdt5uAw.jpg', '2016-10-25', '[14,12,28]', 13.40, '2026-05-12 06:04:39'),
(277, 329865, 'A Chegada', 'Quando seres interplanetários deixam marcas na Terra, a Dra. Louise Banks, uma linguista especialista no assunto, é procurada por militares para traduzir os sinais e desvendar se os alienígenas representam uma ameaça. No entanto, a resposta para todas as perguntas e mistérios coloca em risco  a vida de Louise e a de toda a humanidade.', '/3rDwbFpn6z5HJUgDjpfhEePx8VI.jpg', '2016-11-10', '[18,878,9648]', 15.42, '2026-05-12 06:04:40'),
(278, 62, '2001: Uma Odisséia no Espaço', 'Desde a “Aurora do Homem” (a pré-história), um misterioso monólito negro parece emitir sinais de outra civilização, assim interferindo no nosso planeta. Quatro milhões de anos depois, no século XXI, uma equipe de astronautas liderados pelo experiente David Bowman e Frank Poole é enviada ao planeta Júpiter para investigar o enigmático monólito na nave Discovery, totalmente controlada pelo computador HAL-9000. Entretanto, no meio da viagem, HAL-9000 entra em pane e tenta assumir o controle da nave, eliminando um a um os tripulantes.', '/pVCmLuATJ0lQs4Vx1zUJUN0if2A.jpg', '1968-04-02', '[878,9648,12]', 13.05, '2026-05-12 06:04:40'),
(279, 25221, 'Para Eles, Com Muito Amor', 'A história dos comediantes e cantores Eddie Sparks e Dixie Leonard, que levaram diversão aos soldados da II Guerra Mundial, Coreia e Vietnã. Parceiros por cinco décadas, os dois tiveram fora do palco um relacionamento cheio de risos e lágrimas.', '/cLnndKNJk0QhriUiaYmm56hgEeZ.jpg', '1991-11-22', '[18,10402,35,10752]', 13.15, '2026-05-12 06:04:40'),
(280, 799876, 'O Alfaiate', 'Leonard, um alfaiate inglês costumava fazer ternos na mundialmente famosa Savile Row de Londres. Mas depois de uma tragédia pessoal, ele acabou em Chicago, operando uma pequena alfaiataria em uma parte difícil da cidade, onde ele faz roupas bonitas para as únicas pessoas ao redor que podem pagá-las: uma família de gangsters cruéis.', '/n2CUl7VOOShmsXPuOW6jGvcSu1C.jpg', '2022-02-25', '[80,18,53,9648]', 13.21, '2026-05-12 06:04:40'),
(281, 1280738, '火遮眼', '', '/zP19YO60jwEsfKd5Qf1UvA5uJu8.jpg', '2026-06-05', '[28,80,53]', 15.13, '2026-05-12 06:04:40'),
(282, 819, 'Sleepers: A Vingança Adormecida', 'Quatro garotos da periferia de Nova York são condenados a passar um ano em um centro correcional depois de um trote malsucedido. Trinta anos depois, se reencontram e têm a chance de se vingar das surras e humilhações sofridas durante a detenção.', '/toI7kuNshshr7po1zTLKjBwMyxP.jpg', '1996-10-18', '[80,18,53]', 14.81, '2026-05-12 06:04:48'),
(283, 9806, 'Os Incríveis', 'Beto Pêra e sua mulher Helena estavam entre os maiores super-heróis do mundo, salvando inúmeras vidas e combatendo o mal diariamente. Quinze anos depois, eles foram forçados a adotar novas identidades e a mudar-se para o subúrbio, onde vivem como cidadãos comuns com seus três filhos, Violeta, Flecha e Zezé. Louco para voltar à ação, Beto tem a sua chance quando uma misteriosa ligação o intima a comparecer a uma ilha distante para receber uma missão ultra-secreta. Ele logo descobre que só uma família inteira de super-heróis será capaz de salvar o mundo e impedir sua total destruição.', '/z8k5EhZZTLsCRF8NWjSe6snWNZg.jpg', '2004-10-27', '[28,12,16,10751]', 14.30, '2026-05-12 06:04:49'),
(284, 508947, 'Red: Crescer é Uma Fera', 'Mei, de treze anos, está experimentando a estranheza de ser uma adolescente com uma reviravolta – quando ela fica muito animada, ela se transforma em um panda vermelho gigante.', '/ghQLygaziVKGrocNPRJOztZNvQz.jpg', '2022-03-10', '[16,10751,35,14]', 14.22, '2026-05-12 06:04:49'),
(285, 1627824, 'Rocky Em Uma Gatástrofe', 'Quando um dos planos de Humdinger dá errado, o lar de um Gatinho do Ferro-Velho é destruído, e Rocky acaba assumindo mais do que consegue lidar ao convidar o gatinho para passar a noite na Torre de Vigia. Enquanto o gatinho causa mais confusão do que o esperado, Rocky aprende que até os heróis precisam de ajuda.', '/pqfkJh0CyF00GvR4NIdvJYkJb2F.jpg', '2026-02-27', '[16,10751]', 14.18, '2026-05-12 06:04:49'),
(286, 1303552, 'Horizon: An American Saga - Chapter 3', '', '/uozBQ0BMjTVbvLsv8ZXgKSJRQxv.jpg', NULL, '[37,18]', 7.20, '2026-05-12 06:04:49'),
(287, 106, 'O Predador', 'O major Alan \"Dutch\" Schaefer lidera uma equipe de resgate em uma selva da América Central, para tentar encontrar um ministro estrangeiro e funcionários do governo que saíram da rota e se perderam. O exército acredita que eles estejam nas mãos de guerrilheiros, mas o que eles não imaginam é que a floresta esconde uma ameaça mortal, um ser de outro planeta, fortemente armado, que sente enorme prazer em matar.', '/3RuuLeX487syJrV1olkQCFbHrIv.jpg', '1987-06-12', '[878,28,12,53]', 15.22, '2026-05-12 06:04:49'),
(288, 77, 'Amnésia', 'Leonard está caçando o homem que estuprou e matou sua esposa. Ele tem dificuldades em encontrar o assassino pois sofre de uma forma intratável de perda de memória. Mesmo que ele possa lembrar detalhes da vida antes do acidente, Leonard não consegue lembrar o que aconteceu quinze minutos atrás, onde está indo ou a razão.', '/7leBWM27Q0TUnvmhw6WnFNgGn4G.jpg', '2000-10-11', '[9648,53]', 14.14, '2026-05-12 06:04:49'),
(289, 2109, 'A Hora do Rush', 'Quando a filha de um diplomata chinês é sequestrada em Los Angeles, o cônsul chama o inspector Lee em Hong Kong para ajudar o FBI com o caso. O FBI não se importa com Lee e o deixa de lado no Departamento de Polícia de Los Angeles, pedindo ao detetive James Carter que o vigie. Apesar de Lee e Carter não se suportarem, eles resolvem trabalhar juntos para resolver o caso por conta própria ao descobrirem que foram abandonados tanto pelo FBI quanto pela polícia.', '/sdzr7YU2fPoTwjfsO4gN7ri0S5e.jpg', '1998-09-18', '[28,35,80]', 13.96, '2026-05-12 06:04:50'),
(290, 1450527, 'Forbidden Fruits', '', '/nSlKzxvXWOeDC9qZiwkhGuTAKkq.jpg', '2026-03-26', '[27,35]', 16.46, '2026-05-12 06:04:50'),
(291, 6479, 'Eu Sou a Lenda', 'Robert Neville é um brilhante cientista e o único sobrevivente de uma epidemia que transformou os humanos em mutantes sedentos por sangue. Andando pela cidade de Nova York, ele procura por outros possíveis sobreviventes e tenta achar a cura da praga usando seu próprio sangue, que é imune.', '/j2jb6DwNCPIU2LtUrJ9zoQIGvSz.jpg', '2007-12-12', '[18,878,53]', 14.40, '2026-05-12 06:04:50'),
(292, 272148, 'Darna at Ding', '', '/mBvjbb8756KcL4WODTJXmFkW97p.jpg', '1980-02-08', '[28]', 13.51, '2026-05-12 06:04:50'),
(293, 1621, 'Trocando as Bolas', 'O que pode acontecer quando um magnata de Wall Street encontra um esperto mendigo de rua? Esta é a história de um malandro que troca seu estilo de vida com a de um investidor grã-fino. Daí em diante, a diversão fica mais rica a cada minuto!', '/tYyHmUzo6GT7qjG7OWqo0zsXcoJ.jpg', '1983-06-07', '[35]', 15.11, '2026-05-12 06:04:50'),
(294, 1226578, 'Longlegs - Vínculo Mortal', 'A agente do FBI Lee Harker é designada para o caso de um serial killer que toma rumos inesperados, revelando indícios de ocultismo. Harker descobre uma conexão pessoal com o assassino e precisa detê-lo antes que ele mate novamente.', '/uURBOrqLFyU8iKODcI3t2Xkbhqs.jpg', '2024-07-10', '[80,27,9648]', 13.27, '2026-05-12 06:04:51'),
(295, 447273, 'Branca de Neve', 'Quando a Rainha Má manda matarem sua enteada por inveja de sua beleza, Branca de Neve foge do reino. Ela percorre a floresta e acha uma casinha onde vivem sete anões amigáveis com quem passa viver. Porém, a moça ainda não está a salvo, já que a bruxa planeja dar um fim a sua vida com uma maçã envenenada.', '/mVCNoUc3d1XRAtxwhTdsTyhnnRO.jpg', '2025-03-19', '[10751,14]', 14.14, '2026-05-12 06:04:51'),
(296, 102382, 'O Espetacular Homem-Aranha 2: A Ameaça de Electro', 'O jovem Peter Parker está fascinado com as habilidades que adquiriu como Homem-Aranha. Agora, ele precisa lidar com dois problemas: o retorno de um velho amigo, Harry Osborn, e a chegada de um vilão mais forte e poderoso, Electro.', '/cyMz4OfmNqpuQ02QQOQCbGxQjwK.jpg', '2014-04-16', '[28,12,878]', 14.60, '2026-05-12 06:04:51'),
(297, 857, 'O Resgate do Soldado Ryan', 'Ao desembarcar na Normandia, no dia 6 de junho de 1944, o capitão Miller recebe a missão de comandar um grupo do segundo batalhão para o resgate do soldado James Ryan, caçula de quatro irmãos, dentre os quais três morreram em combate. Por ordens do chefe George C. Marshall, eles precisam procurar o soldado e garantir o seu retorno, com vida, para casa.', '/hMLxNLCXRDd62acfCBn6mIyW1HU.jpg', '1998-07-24', '[10752,18,36]', 14.39, '2026-05-12 06:04:51'),
(298, 378236, 'Emoji: O Filme', 'Textopolis é a cidade onde os Emojis favoritos dos usuários de smartphones vivem e trabalham. Lá, todos eles vivem em função de um sonho: serem usados nos textos dos humanos. Todos estão acostumados a ter somente uma expressão facial - com exceção de Gene, que nasceu com um bug em seu sistema, que o permite trocar de rosto através de um filtro especial. Determinado à se tornar um emoji normal como todos os outros, eles vai encarar uma jornada fantásticas através dos aplicativos de celular mais populares desta geração - e no meio do caminho, claro, fazer novos amigos.', '/g4LW0JOeHyOFRsN6PAyWrH4qbG.jpg', '2017-07-23', '[16,10751,35]', 12.92, '2026-05-12 06:04:51'),
(299, 4247, 'Todo Mundo em Pânico', 'Depois do assassinato de uma bela colega de classe, um grupo de adolescentes desorientados descobre que há um assassino entre eles. A heroína Cindy Campbell e a sua turma de amigos mauricinhos e patricinhas, tentam se proteger do perigo... Mas uma reporter irritante, Gail Hailstorm, simplesmente não os deixa em paz! Parece familiar? Talvez sim, mas essa história repleta de reviravoltas e surpresas horripilantes e humor ultrajante extrapola no gênero de horror e ação.', '/u3azaQ6AgkbAqCcScfHfhHHBNcC.jpg', '2000-07-07', '[35]', 14.74, '2026-05-12 06:04:51'),
(300, 406997, 'Extraordinário', 'Auggie Pullman é um garoto que nasceu com uma deformação facial. Pela primeira vez, ele irá frequentar uma escola regular, como qualquer outra criança. No quinto ano, ele irá precisar se esforçar para conseguir se encaixar em sua nova realidade.', '/2oCqYAm00tMOPNgYPYfYAwMhcPn.jpg', '2017-11-13', '[10751,18]', 14.14, '2026-05-12 06:04:51'),
(301, 228150, 'Corações de Ferro', 'Durante o final da Segunda Guerra Mundial, um grupo de cinco soldados americanos é encarregado de atacar os nazistas dentro da própria Alemanha. Apesar de estarem em quantidade inferior e terem poucas armas, eles são liderados pelo enfurecido Wardaddy, sargento que pretende levá-los à vitória, enquanto ensina o novato Norman a lutar.', '/tVZXsjBC9HIoKv6WnAv0nWObbrT.jpg', '2014-10-15', '[10752,18,28]', 14.60, '2026-05-12 06:04:51'),
(302, 696393, 'Alerta Apocalipse', 'Quando um fungo altamente perigoso escapa de um laboratório secreto, Robert Quinn, um ex-agente de bioterrorismo que só queria curtir a aposentadoria em paz, é chamado de volta à ação. Ao lado de Travis e Naomi, dois jovens funcionários que definitivamente não ganham o suficiente para isso, ele precisa enfrentar uma ameaça invisível e fora de controle. Em uma corrida contra o tempo, o trio descobre que salvar o mundo dá muito mais trabalho do que parece.', '/3Ap6J9pYqgrxQaYWYdX2fyBYBWF.jpg', '2026-01-22', '[27,878,35]', 22.75, '2026-05-12 06:05:25'),
(303, 664767, 'Mortal Kombat Legends: A Vingança de Scorpion', 'Após o massacre cruel de sua família pelo mercenário Sub-Zero, Hanzo Hasashi é exilado no tortuoso Netherrealm, lá, em troca de sua servidão ao sinistro Quan Chi, ele tem a chance de vingar sua família - e ressuscita como Scorpion, uma alma perdida e vingativa. De volta ao Earthrealm, Lord Raiden reúne uma equipe de guerreiros de elite - o monge Shaolin Liu Kang, a oficial das Forças Especiais Sonya Blade e o ator de ação Johnny Cage - um grupo improvável de heróis com uma chance de salvar a humanidade. Para fazer isso, eles devem derrotar a horda de gladiadores do Outworld de Shang Tsung e vencer o torneio Mortal Kombat.', '/zO5913BWcWYrhgACNpaaw9CCycX.jpg', '2020-04-12', '[16,28,14]', 24.50, '2026-05-12 06:05:25'),
(304, 1049471, 'Consequência', 'Reef Hawk, o queridinho de Hollywood desde os seis anos, não está bem. Ao descobrir um plano de extorsão ligado a um vídeo misterioso, Reef decide embarcar em uma jornada de redenção para se retratar, confrontar seus demônios e evitar o cancelamento.', '/dTQZwcItQNEeSjpk3BYKYg27v9t.jpg', '2026-04-06', '[35,18]', 22.33, '2026-05-12 06:05:25'),
(305, 1659087, '180', 'Depois que um incidente no trânsito deixa seu filho em estado crítico, um pai com sangue nos olhos embarca em um caminho sombrio de caos e vingança.', '/9ISjrhA38HpSSGtfiCk8lpziC3K.jpg', '2026-04-16', '[53,80,18,10770]', 21.66, '2026-05-12 06:05:25'),
(306, 218, 'O Exterminador do Futuro', 'Em um futuro próximo, a guerra entre humanos e máquinas foi iniciada. Com a tecnologia a seu dispor, um plano inusitado é arquitetado pelas máquinas ao enviar para o passado um andróide com a missão de matar a mãe daquele que viria a se transformar num líder e seu pior inimigo. Contudo, os humanos também conseguem enviar seu representante para proteger a mulher e tentar garantir o futuro da humanidade.', '/fo4SSoNT1ASI4JP7dOLrosWNWKa.jpg', '1984-10-26', '[28,53,878]', 19.62, '2026-05-12 06:05:26'),
(307, 1218925, 'Chainsaw Man – O Filme: Arco da Reze', 'Denji trabalhava como Caçador de Demônios para a yakuza, tentando pagar a dívida que herdou de seus pais, até que um dia, ele é traído e morre. Em seus últimos momentos de consciência, ele forma um pacto com Pochita e essa fusão cria o Homem-Motosserra. Agora, em uma guerra brutal contra demônios, caçadores e inimigos secretos, uma garota misteriosa chamada Reze entrou em seu universo e Denji precisa enfrentar sua batalha mais perigosa até hoje, movido pelo amor em um mundo onde a sobrevivência não conhece regras.', '/tj1XhCQ2Rw2sT2o7lIdqPIYvjsx.jpg', '2025-09-19', '[16,28,10749,14]', 28.88, '2026-05-12 06:05:26'),
(308, 19995, 'Avatar', 'Apesar de não ter mais os movimentos da perna, o ex-fuzileiro naval Jake Sully ainda sente que pode ser um guerreiro. Sua intuição começa a se tornar realidade quando ele viaja anos-luz até a estação espacial montada no Planeta Pandora. Habitado por grandes seres azuis, os Na´vi, o local tem uma atmosfera fatal para qualquer terrestre. Por isso, oficiais criaram o programa Avatar, em que um corpo biológico, híbrido de humano e Na´vi, pode ser comandado a distância.', '/jKKHa8MvDpYh4bf4rAmgC5uNKvR.jpg', '2009-12-16', '[878,28,12]', 24.56, '2026-05-12 06:05:26'),
(309, 617126, 'Quarteto Fantástico: Primeiros Passos', 'No vibrante cenário de um mundo retrofuturista inspirado nos anos 1960, a Primeira Família da Marvel é forçada a equilibrar seus papéis como heróis com a força de seus laços familiares, enquanto defendem a Terra de um deus espacial voraz chamado Galactus e sua enigmática arauta, a Surfista Prateada.', '/8F2vIxWycANHW763lnx2hJVtjDC.jpg', '2025-07-23', '[878,12,28]', 21.71, '2026-05-12 06:05:26'),
(310, 348, 'Alien: O Oitavo Passageiro', 'Quando a tripulação da sonda espacial Nostromo responde a um pedido de socorro vindo de um planeta inóspito, eles descobrem uma forma de vida mortal que se reproduz dentro de humanos. Agora, a tripulação deve lutar para permanecer viva e impedir que a criatura chegue até a Terra.', '/rFHzJrkO1kNIezb6rFog5oCJUEn.jpg', '1979-05-25', '[27,878]', 25.69, '2026-05-12 06:05:26'),
(311, 1515899, 'Billie Eilish - Hit Me Hard and Soft: The Tour in 3D', 'Codirigido por Billie Eilish em parceria com o visionário cineasta James Cameron, o longa traz performances ao vivo em 3D de hits como “LUNCH”, “Birds of a Feather” e “CHIHIRO”, além de contar um pouco dos bastidores da turnê do álbum \"HIT ME HARD AND SOFT\".', '/rGZyH9erzIVnk5R7NEF9V38nCQu.jpg', '2026-05-06', '[10402,99]', 23.48, '2026-05-12 06:05:26'),
(312, 1184918, 'Robô Selvagem', 'Um robô – unidade ROZZUM 7134, abreviadamente “Roz” – naufraga em uma ilha desabitada e deve aprender a se adaptar ao ambiente hostil, gradualmente construindo relacionamentos com os animais da ilha e se tornando o pai adotivo de um filhote de ganso órfão.', '/gAHNIZKG8fmK7njOTpMmLKJXiag.jpg', '2024-09-12', '[10751,16,878,12]', 23.99, '2026-05-12 06:05:27'),
(313, 121, 'O Senhor dos Anéis: As Duas Torres', 'Após a captura de Merry e Pippin pelos orcs, a Sociedade do Anel é dissolvida. Frodo e Sam seguem sua jornada rumo à Montanha da Perdição para destruir o anel e serão obrigados a confiar no misterioso Gollum. Enquanto isso, Aragorn, o elfo e o arqueiro Legolas e o anão Gimli partem para resgatar os hobbits sequestrados e chegam ao reino de Rohan, onde o rei Théoden foi vítima de uma maldição mortal de Saruman.', '/mCs8vxvScCqVM3YFMQIdbrdFEhu.jpg', '2002-12-18', '[12,14,28]', 23.11, '2026-05-12 06:05:27'),
(314, 1408208, 'Exit 8', 'Um homem preso em uma passagem infinita de metrô parte em busca da Saída 8. As regras de sua jornada são simples: não ignore nada fora do comum; se descobrir alguma anomalia, volte imediatamente; caso contrário, continue; em seguida, saia pela Saída 8. Mas, mesmo um único descuido o enviará de volta ao início. Será que ele alcançará seu objetivo e escapará deste corredor infinito?', '/naszJRWpzgbrR9vdifVoQ9IpNqW.jpg', '2025-08-28', '[27,9648]', 20.99, '2026-05-12 06:05:27'),
(315, 939243, 'Sonic 3: O Filme', 'Sonic, Knuckles e Tails se reúnem contra um novo e poderoso adversário, Shadow, um vilão misterioso com poderes diferentes de tudo que eles já enfrentaram antes. Com suas habilidades superadas em todos os sentidos, a Equipe Sonic deve buscar uma aliança improvável na esperança de parar Shadow e proteger o planeta.', '/tfM1T6tAivjvy0sLwt6Y9WvlmzB.jpg', '2024-12-19', '[28,878,35,10751]', 21.33, '2026-05-12 06:05:27'),
(316, 991494, 'Bob Esponja: Em Busca da Calça Quadrada', 'Bob Esponja e seus amigos da Fenda do Bikini embarcam na maior aventura de suas vidas. Ao tentar provar que é grandão, ele acaba invocando o temido pirata fantasma Holandês Voador, que arrasta Bob Esponja e Patrick para uma jornada caótica no submundo. Enfrentando desafios enormes e com uma equipe de resgate em seu encalço, Bob Esponja descobre que a verdadeira coragem aparece quando os amigos encaram o desconhecido juntos.', '/obDYToEfPFNMKW6x0eamCrjTMzK.jpg', '2025-12-16', '[12,16,35,10751,14]', 21.98, '2026-05-12 06:05:27'),
(317, 10138, 'Homem de Ferro 2', 'Em um mundo ciente da existência do Homem de Ferro, o inventor bilionário Tony Stark sofre pressão de todos os lados para compartilhar sua tecnologia com as forças armadas. Ele resiste para divulgar os segredos de sua inigualável armadura, com medo de que estas informações caiam nas mãos erradas.', '/vzROjQbgKWMVf2EldXipCcjpuBL.jpg', '2010-04-28', '[12,28,878]', 21.56, '2026-05-12 06:05:27');
INSERT INTO `movies` (`id`, `tmdb_id`, `title`, `overview`, `poster_path`, `release_date`, `genre_ids`, `popularity`, `created_at`) VALUES
(318, 269149, 'Zootopia: Essa Cidade é o Bicho', 'Em uma cidade de animais antropomórficos, uma raposa fugitiva vigarista e um coelho policial recruta precisam trabalhar juntos para desvendar uma conspiração.', '/ncqVGCX9P3EKQfsOXiB3XxQ0Dip.jpg', '2016-02-11', '[16,12,10751,35]', 23.25, '2026-05-12 06:05:27'),
(319, 1726, 'Homem de Ferro', 'Tony Stark é um industrial bilionário, que também é um brilhante inventor. Ao ser sequestrado ele é obrigado por terroristas a construir uma arma devastadora mas, ao invés disto, constrói uma armadura de alta tecnologia que permite que fuja de seu cativeiro. A partir de então ele passa a usá-la para combater o crime, sob o alter ego do Homem de Ferro.', '/mqN7RxojEiPoh3FTSTwOtwg7KAu.jpg', '2008-04-30', '[28,878,12]', 21.85, '2026-05-12 06:05:27'),
(320, 1241982, 'Moana 2', 'Depois de receber um chamado inesperado de seus ancestrais navegadores, Moana vai viajar para mares distantes da Oceania, em águas perdidas em uma aventura perigosa.', '/dnqgkKoIGf6hErzRm6VtaK1OJrD.jpg', '2024-11-21', '[12,16,35,10751,14]', 21.95, '2026-05-12 06:05:28'),
(321, 1078605, 'A Hora do Mal', 'Quando todas as crianças de uma mesma classe, exceto uma, somem misteriosamente, na mesma noite e exatamente ao mesmo tempo, todos da cidade começam a se questionar quem ou o que está por trás deste estranho desaparecimento.', '/psEJSjQr6I9GSJTdW28CKC4Kffs.jpg', '2025-08-04', '[27,9648]', 21.26, '2026-05-12 06:05:28'),
(322, 38, 'Brilho Eterno de uma Mente sem Lembranças', 'Joel se surpreende ao saber que seu amor verdadeiro, Clementine, o apagou completamente de sua memória. Ele decide fazer o mesmo, mas muda de ideia. Preso dentro da própria mente enquanto os especialistas se mantêm ocupados em seu apartamento, Joel precisa avisá-los para parar.', '/zqbwK2ugTPauBQwzcNAM3PxVoww.jpg', '2004-03-19', '[878,18,10749]', 17.55, '2026-05-12 06:05:31'),
(323, 105, 'De Volta para o Futuro', 'Marty McFly, um típico adolescente americano dos anos 80, acidentalmente é enviado de volta ao ano de 1955 em um carro modificado para ser uma máquino do tempo, inventada por um cientista louco. Durante sua fantástica e maluca viagem no tempo, McFly tem que fazer com que seus futuros pais se encontrem e se apaixonem, para que assim ele possa ir de volta para o futuro.', '/i996T0lI1fGtFEowiH3V6eZthL0.jpg', '1985-07-03', '[12,35,878]', 19.32, '2026-05-12 06:05:31'),
(324, 324857, 'Homem-Aranha: No Aranhaverso', 'Miles Morales é um jovem negro do Brooklyn que se tornou o Homem-Aranha inspirado no legado de Peter Parker, já falecido. Entretanto, ao visitar o túmulo de seu ídolo em uma noite chuvosa, ele é surpreendido com a presença do próprio Peter, vestindo o traje do herói aracnídeo sob um sobretudo. A surpresa fica ainda maior quando Miles descobre que ele veio de uma dimensão paralela, assim como outras variações do Homem-Aranha.', '/gte2cJ3mtc2I8hZyXwRTzyclKuC.jpg', '2018-12-06', '[16,28,12,878]', 21.00, '2026-05-12 06:05:32'),
(325, 410119, '足本玉蒲團', '', '/3NwBn6zPY6yXCqfxEHmEgGh8Jgc.jpg', '1987-10-15', '[18,14,10749]', 17.05, '2026-05-12 06:05:32'),
(326, 177572, 'Operação Big Hero', 'O grande robô inflável está sempre a postos para cuidar de Hiro Hamada. Quando algo devastador assola a cidade, o menino prodígio, seus amigos e o robô formam um grupo de heróis para combater o mal.', '/5EodFesjReSDlX1c0I5ANZijBFy.jpg', '2014-10-24', '[12,10751,16,28,35]', 18.84, '2026-05-12 06:05:32'),
(327, 64641, 'La ragazzina', '', '/eb4mMyocL1XdaI6DPexyZGMo0sF.jpg', '1974-02-28', '[10749,18]', 19.67, '2026-05-12 06:05:32'),
(328, 122917, 'O Hobbit: A Batalha dos Cinco Exércitos', 'O dragão Smaug lança sua fúria ardente contra a Cidade do Lago que fica próxima da montanha de Erebor. Bard consegue derrotá-lo, mas, rapidamente, sem a ameaça do dragão, inicia-se uma batalha pelo controle de Erebor e sua riqueza. Os anões, liderados por Thorin, adentram a montanha e estão dispostos a impedir a entrada de elfos, anões e orcs. Bilbo Bolseiro e Gandalf tentam impedir a guerra.', '/wRKwrfQ7p0ttrb09G3mcOSyN1pk.jpg', '2014-12-10', '[28,12,14]', 17.52, '2026-05-12 06:05:32'),
(329, 674, 'Harry Potter e o Cálice de Fogo', 'Em seu 4º ano na Escola de Magia e Bruxaria de Hogwards, Harry Potter é misteriosamente selecionado para participar do Torneio Tribruxo, uma competição internacional em que precisará enfrentar alunos mais velhos e experientes de Hogwards e também de outras escolas de magia. Além disso a aparição da marca negra de Voldemort ao término da Copa Mundial de Quadribol põe a comunidade de bruxos em pânico, já que sinaliza que o temido bruxo está prestes a retornar.', '/5oWB3hjzyECRBAjgWkmZinxl9qA.jpg', '2005-11-16', '[12,14]', 19.07, '2026-05-12 06:05:32'),
(330, 933720, 'Lion', '', '/5WXQzISL6RVRMU1b9DiyHtHLeDM.jpg', '2019-09-05', '[12,16]', 16.76, '2026-05-12 06:05:33'),
(331, 13576, 'Michael Jackson\'s This Is It', '“This Is It” oferece aos fãs de Michael e apreciadores de música de todo mundo, uma rara e especial visão dos bastidores do artista, mostrando o desenvolvimento, a criação e os ensaios dos espetáculos que já tinham lotação esgotada e iriam começar no verão de 2009 na O2 Arena, em Londres. Seguindo uma narrativa entre Abril e Junho de 2009, o filme representa mais de 100 horas de bastidores apresentando Michael Jackson ensaiando diversas músicas para os shows.', '/boeT9GbgZPYJnv6NtjoaGT3IagK.jpg', '2009-10-28', '[10402,99]', 20.40, '2026-05-12 06:05:33'),
(332, 1119449, 'Boa Sorte, Divirta-se, Não Morra', 'Um homem vindo do futuro chega a uma lanchonete em Los Angeles, onde precisa recrutar a combinação exata de clientes insatisfeitos para acompanhá-lo em uma missão de uma noite e seis quarteirões para salvar o mundo da ameaça terminal de uma inteligência artificial descontrolada.', '/uy9KPHgJpxXHCzn4vPzuGkApzC8.jpg', '2026-02-13', '[878,28,35]', 17.44, '2026-05-12 06:05:33'),
(333, 346364, 'It: A Coisa', 'Na cidade de Derry, no Maine, sete jovens se juntam para combater uma criatura sobrenatural que está assombrando a sua cidade por séculos. Chamado de Pennywise – O Palhaço Dançarino, a Coisa é um monstro de força absoluta que toma a forma dos medos mais horrorosos das pessoas. Ameaçados por seus piores pesadelos, a única maneira dos jovens amigos sobreviverem à Coisa é se continuarem juntos.', '/uYxz0lIiNgErrPhQbSjUdwYxtFc.jpg', '2017-09-06', '[27,53,18]', 19.81, '2026-05-12 06:05:33'),
(334, 829487, 'Meu Nome é Agneta', 'Ansiosa por um recomeço e desempregada, Agneta aceita trabalhar como au pair na Provença, uma mudança de cenário muito bem-vinda — acompanhada de um despertar inesperado.', '/jFFPtC0kj3MFspj76enfKIGNxqy.jpg', '2026-04-28', '[35,18,10749]', 16.29, '2026-05-12 06:05:33'),
(335, 338803, '간신', '', '/wjHi19IHTq6VmOtSENnLbkhUiMk.jpg', '2015-05-21', '[18,36,80]', 18.74, '2026-05-12 06:05:33'),
(336, 385687, 'Velozes & Furiosos 10', 'Dom Toretto enfrenta seu maior desafio até agora: a corrida para salvar a família de um inimigo cheio de rancor e fúria no volante.', '/xNqt1Om0IlUhDOjZRCL5ewoazVV.jpg', '2023-05-17', '[28,80,53]', 19.83, '2026-05-12 06:05:34'),
(337, 138843, 'Invocação do Mal', 'Harrisville, Rhode Island, Estados Unidos, 1968. Os investigadores paranormais Ed e Lorraine Warren trabalham para ajudar uma família aterrorizada por uma presença sombria em sua fazenda. Forçados a confrontar uma entidade poderosa, os Warrens se vêem presos no caso mais aterrorizante de suas vidas. Baseado numa história real.', '/1NxHKZW5DPbUFtbF3MxbdSyxRqU.jpg', '2013-07-18', '[27,53]', 18.95, '2026-05-12 06:05:34'),
(338, 76341, 'Mad Max: Estrada da Fúria', 'Em um mundo apocalíptico, Max Rockatansky acredita que a melhor forma de sobreviver é não depender de ninguém. Porém, após ser capturado pelo tirano Immortan Joe e seus rebeldes, Max se vê no meio de uma guerra mortal, iniciada pela imperatriz Furiosa que tenta salvar um grupo de garotas. Também tentando fugir, Max aceita ajudar Furiosa. Dessa vez, o tirano Joe está ainda mais implacável pois teve algo insubstituível roubado.', '/tH64gzAHDFg7EFcgfkkZyHdGM5P.jpg', '2015-05-13', '[28,12,878]', 16.73, '2026-05-12 06:05:34'),
(339, 1156593, 'Sua Culpa', 'O amor entre Noah e Nick aparenta ser inabalável, apesar das tentativas de seus pais de separá-los. Mas o emprego dele, e a entrada dela na faculdade abrem suas vidas para novos relacionamentos. O retorno de uma ex-namorada vingativa e da mãe de Nick, com intenções obscuras, vão balançar não só o relacionamento deles, mas também de toda a família Leister. Quando tantas pessoas buscam destruir um relacionamento, será que ele consegue sobreviver?', '/mdaODPyPbAwIeQwgBv7u8CMsxIl.jpg', '2024-12-26', '[18,10749]', 18.49, '2026-05-12 06:05:34'),
(340, 17903, 'Flor Congelada', 'Um drama histórico ambientado na dinastia Koryo e focado no relacionamento entre um rei e seu guarda-costas. Sob o domínio da dinastia Yuan China, o rei da dinastia Goryeo Coréia é pressionado a produzir um sucessor no trono. Incapaz de fazer amor com sua rainha, porque ele está apaixonado por seu guarda-costas, Hong Lim, o rei pede que os dois dormam juntos. Esse contato sexual formula um amor proibido entre Hong Lim e a rainha.', '/atXHQaVfMTOMENR2QtqauPguaXt.jpg', '2008-12-30', '[18]', 18.06, '2026-05-12 06:05:34'),
(341, 22512, 'Sexo, Pudor e Lágrimas', 'O intelectual Carlos aparentemente não está sendo carinhoso o suficiente com Ana, sua esposa. Após muitos anos viajando, Tomas, um amigo do casal, reaparece para visitá-los. Enquanto isso, no apartamento da frente, a insatisfeita Andrea e Miguel, seu marido mulherengo, recebem Maria em sua casa. A presença dos convidados na vida dos dois casais acaba despertando sentimentos reprimidos e reflexões sobre a vida amorosa de todos.', '/qP2t996caP9rLecB6FSfNXa0MKx.jpg', '1999-06-18', '[35,18,10749]', 16.78, '2026-05-12 06:05:34'),
(342, 1175942, 'Os Caras Malvados 2', 'Os agora reformados Bad Guys estão tentando (muito, muito mesmo) ser bons, mas em vez disso se veem sequestrados para um assalto de alto risco e alcance mundial, arquitetado por uma nova equipe de criminosos que eles nunca imaginaram: as Bad Girls.', '/dbpNAldCtWjotI4vEiphPrz8DJh.jpg', '2025-07-24', '[10751,35,80,12,16]', 19.32, '2026-05-12 06:06:48'),
(343, 109445, 'Frozen: Uma Aventura Congelante', 'A destemida e otimista Anna sai em uma jornada épica, ao lado de Kristoff e sua leal rena Sven, para encontrar sua irmã Elsa, cujos poderes congelantes aprisionaram o reino de Arendelle em um inverno eterno. Encontrando condições de Everest, trolls místicos e um hilário boneco de neve chamado Olaf, Anna e Kristoff enfrentam obstáculos em uma corrida para salvar o reino.', '/hOZKUJGN0m717LRSQDxhgABqWrf.jpg', '2013-11-20', '[16,10751,12,14]', 18.63, '2026-05-12 06:06:48'),
(344, 552524, 'Lilo & Stitch', 'Stitch, um alienígena, chega ao planeta Terra após fugir de sua prisão e tenta se passar por um cachorro para se camuflar. As coisas mudam quando Lilo, uma travessa menina, o adota de um abrigo de animais. Juntos, eles aprendem os valores da amizade e família.', '/m58Oxr3OZZbP2kTX2tj8TiAMLSv.jpg', '2025-05-17', '[10751,878,35]', 18.82, '2026-05-12 06:06:48'),
(345, 111, 'Scarface', 'Após receber residência permanente nos EUA em troca do assassinato de um oficial do governo cubano, Tony Montana se torna chefe do tráfico de drogas em Miami. A pressão da polícia, as guerras com cartéis colombianos e sua própria paranoia servem para alimentar as chamas de sua eventual queda.', '/b089YkBDJjOGDQxXkOXBR06Lz2Y.jpg', '1983-12-09', '[28,80,18]', 17.74, '2026-05-12 06:06:48'),
(346, 1643, 'Último Tango em Paris', 'Enquanto procura um apartamento em Paris, uma bela jovem (Maria Schneider) conhece um americano (Marlon Brando), cuja esposa cometeu suicídio recentemente. Instantaneamente um deseja o outro ardentemente e iniciam naquele momento um tórrido affair. Eles combinam que não revelariam nada de suas vidas, nem mesmo seus nomes, sendo que o objetivo dos encontros seria basicamente sexo. Mas, gradativamente, os acontecimentos vão fugindo do controle de ambos.', '/gLyCJxqEpXoSn1Ic4ngfZ7E1jJO.jpg', '1972-12-15', '[18,10749]', 18.76, '2026-05-12 06:06:48'),
(347, 396535, 'Invasão Zumbi', 'A Coreia do Sul decreta estado de emergência após um vírus desconhecido tomar conta do país. Algumas pessoas tentam fugir de zumbis e ficam presas em um trem-bala que está a caminho de Busan, a única cidade que não foi afetada pelo vírus.', '/QqHtwk0oHYed26zra9WGQGyBSm.jpg', '2016-07-20', '[27,53,28,12]', 19.11, '2026-05-12 06:06:48'),
(348, 603692, 'John Wick 4: Baba Yaga', 'Com o preço por sua cabeça cada vez maior, John Wick leva sua luta contra a alta mesa global enquanto procura os jogadores mais poderosos do submundo, de Nova York a Paris, de Osaka a Berlim.', '/rXTqhpkpj6E0YilQ49PK1SSqLhm.jpg', '2023-03-21', '[28,53,80]', 18.75, '2026-05-12 06:06:48'),
(349, 429617, 'Homem-Aranha: Longe de Casa', 'Peter Parker está em uma viagem de duas semanas pela Europa, ao lado de seus amigos de colégio, quando é surpreendido pela visita de Nick Fury. Convocado para mais uma missão heroica, ele precisa enfrentar vários vilões que surgem em cidades-símbolo do continente, como Londres, Paris e Veneza, e também a aparição do enigmático Mysterio.', '/8V0hpq8BUzauB06eEfr7AmyTzbK.jpg', '2019-06-28', '[28,12,878]', 16.15, '2026-05-12 06:06:49'),
(350, 14160, 'Up: Altas Aventuras', 'Carl Fredricksen é um vendedor de balões que, aos 78 anos, está prestes a perder a casa em que sempre viveu com sua esposa, a falecida Ellie. Após um incidente, Carl é considerado uma ameaça pública e forçado a ser internado. Para evitar que isto aconteça, ele põe balões em sua casa, fazendo com que ela levante voo. Carl quer viajar para uma floresta na América do Sul, onde ele e Ellie sempre desejaram morar, mas descobre que um problema embarcou junto: Russell, um menino de 8 anos.', '/oo5gvGDIiPwbXc3R0snZIuOc517.jpg', '2009-05-28', '[16,35,10751,12]', 18.71, '2026-05-12 06:06:49'),
(351, 453395, 'Doutor Estranho no Multiverso da Loucura', 'Doutor Estranho, com a ajuda de aliados místicos antigos e novos, atravessa as perigosas realidades alternativas e alucinantes do Multiverso para enfrentar um novo adversário misterioso.', '/7pLIVfovuIf2KQOOvMsKx3Lanrg.jpg', '2022-05-04', '[14,28,12]', 16.76, '2026-05-12 06:06:49'),
(352, 216015, 'Cinquenta Tons de Cinza', 'Anastasia Steele (Dakota Johnson) é uma estudante de literatura de 21 anos, recatada e virgem. Uma dia ela deve entrevistar para o jornal da faculdade o poderoso magnata Christian Grey (Jamie Dornan). Nasce uma complexa relação entre ambos: com a descoberta amorosa e sexual, Anastasia conhece os prazeres do sadomasoquismo, tornando-se o objeto de submissão do sádico Grey.', '/t4kR6H71anOV85qzjOLlr9uVdFJ.jpg', '2015-02-11', '[18,10749,53]', 15.93, '2026-05-12 06:06:49'),
(353, 744, 'Top Gun - Ases Indomáveis', 'A escola naval de pilotos é onde o melhor dos melhores treinam para refinar suas habilidades de voo de elite. Quando o piloto Maverick é enviado para a escola, sua atitude irresponsável e comportamento arrogante o colocam em desacordo com os outros pilotos, especialmente Iceman. Porém Maverick não está apenas competindo para ser o piloto superior de caça, ele também está lutando pela atenção de sua bonita instrutora de voo, Charlotte Blackwood.', '/dDrMtnVgtDeecIgNchb9F8JcO5w.jpg', '1986-05-16', '[28,18,10749]', 19.52, '2026-05-12 06:06:49'),
(354, 77338, 'Intocáveis', 'Quando um ex-presidiário é contratado para cuidar de um aristocrata francês, seu novo trabalho se torna uma aventura imprevisível. Acelerar uma Maserati em Paris, seduzir mulheres, e fazer parapente sobre os Alpes é apenas o começo, pois ele vira o mundo da classe alta de Paris de cabeça para baixo.', '/2tAzFC2xUAXEx96l5Xixb6WLAyO.jpg', '2011-11-02', '[18,35]', 16.07, '2026-05-12 06:06:49'),
(355, 1585476, 'Kevin Costner apresenta: O Primeiro Natal', 'Kevin Costner apresenta o especial que explora a extraordinária jornada de Maria e José enquanto enfrentam as dificuldades, provações e triunfos que cercam o nascimento de Jesus Cristo, oferecendo uma maneira inspiradora de vivenciar o verdadeiro significado do Natal.', '/iR4AaNGQUQwMxgOLjtXZoiHaumn.jpg', '2025-12-09', '[99,18]', 9.00, '2026-05-12 06:06:49'),
(356, 1357633, 'Solo Leveling -Segundo Despertar-', 'Mais de uma década após o surgimento dos “portões” que ligam os mundos, despertando “caçadores” com superpoderes, o caçador mais fraco, Sung Jinwoo, encontra uma masmorra dupla e aceita uma missão misteriosa, tornando-se o único capaz de subir de nível, mudando seu destino. Uma recapitulação da primeira temporada, juntamente com uma prévia exclusiva dos dois primeiros episódios da tão esperada segunda temporada, em uma experiência teatral memorável para os fãs.', '/iU1fG893IXb8wdV70D23YTJDrjR.jpg', '2024-11-26', '[28,12,14,16]', 18.08, '2026-05-12 06:06:49'),
(357, 823464, 'Godzilla e Kong: O Novo Império', 'O poderoso Kong e o temível Godzilla se unem contra uma colossal ameaça mortal escondida no mundo dos humanos, que ameaça a existência de sua espécie e da nossa. Mergulhando profundamente nos mistérios da Ilha da Caveira e nas origens da Terra Oca, o filme irá explorar a antiga batalha de Titãs que ajudou a forjar esses seres extraordinários e os ligou à humanidade para sempre.', '/fWSGD2yrzz6hscocnMD8AEXIThk.jpg', '2024-03-27', '[28,12,878]', 16.80, '2026-05-12 06:06:50'),
(358, 862, 'Toy Story: Um Mundo de Aventuras', 'Buzz Lightyear é o novo e sofisticado astronauta de brinquedo do garoto Andy. Buzz não imaginava que encontraria um rival: Woody, um cowboy de brinquedo que, dominado pelo ciúme, acredita ter perdido um lugar precioso no coração do seu dono. Os dois brinquedos vivem brigando até que vão parar nas garras do vizinho, um verdadeiro destruidor de brinquedos. Agora, mais do que nunca, Buzz e Woody precisam precisam se unir para escapar do perigo. Com a ajuda de seus amigos da caixa de brinquedos, eles vão viver uma incrível aventura.', '/6AafgfifXkFS4g2xGJZIwsPQK6P.jpg', '1995-11-22', '[10751,35,16,12]', 20.05, '2026-05-12 06:06:50'),
(359, 11036, 'Diário de uma Paixão', 'Na década de 40, o operário Noah Calhoun e a rica Allie estão desesperadamente apaixonados, mas os pais da jovem não aprovam o namoro. Quando Noah vai para a Segunda Guerra Mundial, parece ser o fim do romance. Enquanto isso, Allie se envolve com outro homem. Mas quando Noah retorna para a pequena cidade anos mais tarde, próximo ao casamento de Allie, logo se torna claro que a paixão ainda não acabou.', '/hO6k34ZNDwWzgcnzFbqYf2Rjg5W.jpg', '2004-06-25', '[10749,18]', 18.15, '2026-05-12 06:06:50'),
(360, 1303055, 'A Breed Apart', 'Violet, uma rebelde que procura cães abandonados em uma ilha remota, se encontra em uma situação angustiante, cheia de terror e caos movido a adrenalina.', '/6IiNUUV6H2W1wUc8e1w4GfuQCOE.jpg', '2025-05-16', '[27,9648,28]', 15.35, '2026-05-12 06:06:50'),
(361, 12444, 'Harry Potter e as Relíquias da Morte - Parte 1', 'Harry, Ron e Hermione estão determinados em sua missão de descobrir e acabar com o segredo da imortalidade e do poder de destruição de Voldemort – os Horcruxes. Fugitivos e sozinhos, os três amigos devem apenas contar uns com os outros, agora mas do que nunca... Mas as Forças das Trevas no caminho ameaçam separá-los para sempre.', '/67FVFOTaeBUQnimhCWpUkDawDct.jpg', '2010-11-17', '[12,14]', 17.89, '2026-05-12 06:06:50'),
(362, 940551, 'Patos!', 'A família Mallard está um pouco refém da rotina. Enquanto Mack, o pai, se contenta em manter sua família segura nos arredores de um lago da Nova Inglaterra para sempre, Pam, a mãe, está ansiosa para agitar as coisas e mostrar a seus filhos – o adolescente Dax e a patinha Gwen – o mundo inteiro. Quando uma família de patos migratórios aterrissa em seu lago com histórias emocionantes de lugares distantes, Pam convence Mack a embarcar em uma viagem em família, via Nova York, para a Jamaica tropical.', '/wXWnUhdnSuADRp9w7aAZNHx682v.jpg', '2023-12-06', '[10751,35,12,16]', 12.74, '2026-05-12 06:06:54'),
(363, 8392, 'Meu Amigo Totoro', 'Duas irmãs se mudam para o campo com o pai para ficarem mais próximas da mãe hospitalizada e descobrem que as árvores ao redor são habitadas por Totoros, espíritos mágicos da floresta. Quando a mais nova foge de casa, a irmã mais velha busca a ajuda dos espíritos para encontrá-la.', '/23KKTxDg6rxZVc66bloQQdPSr29.jpg', '1988-04-16', '[14,16,10751]', 12.61, '2026-05-12 06:06:54'),
(364, 449985, 'Tripla Ameaça', 'A filha de um bilionário torna-se o alvo de um perigoso e eficiente cartel criminoso. O que eles não contavam, é que sua proteção passaria a ser três implacáveis mercenários - dois lutadores passando por dificuldades e um terceiro que jurou vingança contra os outros - lutando com unhas e dentes para impedir que os assassinos alcancem seu alvo.', '/dgdLSEBm5IrcmquZDKA0ZowsWbd.jpg', '2019-03-19', '[53,28]', 11.94, '2026-05-12 06:06:54'),
(365, 1064213, 'Anora', 'Anora, uma jovem profissional do sexo que trabalha nas noites do Brooklyn, pode se tornar a Cinderela da sua própria história quando encontra e casa, por impulso, com o filho de um oligarca russo. Mas quando a notícia chega à Rússia, seu conto de fadas fica ameaçado com a chegada dos pais dele a Nova York para cancelar o casamento.', '/xmFdNzbUiT5XmH6rbIVGYDQHGeo.jpg', '2024-10-14', '[18,35,10749]', 13.76, '2026-05-12 06:06:55'),
(366, 588228, 'A Guerra do Amanhã', 'Em 2051, a humanidade está perdendo uma guerra global contra uma espécie mortal de alienígenas. Para garantir a sobrevivência dos humanos, soldados e civis do presente são transportados para o futuro e se juntam à luta, entre eles Dan Forester, um pai de família determinado a salvar o mundo para sua filha.', '/lWQ3hI78Az2RHfzDpEuvougqUz7.jpg', '2021-09-03', '[28,878,12]', 12.43, '2026-05-12 06:06:55'),
(367, 78, 'Blade Runner: O Caçador de Andróides', 'No início do século 21, uma grande corporação desenvolve um robô que é mais forte e ágil que o ser humano e se equiparando em inteligência. São conhecidos como \"replicantes\" e utilizados como escravos na colonização e exploração de outros planetas. Mas, quando um grupo dos robôs mais evoluídos provoca um motim em uma colônia fora da Terra, este incidente faz os replicantes serem considerados ilegais na Terra, sob pena de morte. A partir de então, policiais de um esquadrão de elite conhecidos como \"Blade Runner\", têm ordem de atirar para matar em replicantes encontrados na Terra. Mas tal ato não é chamado de \"execução\" e sim de \"remoção\". Até que, em novembro de 2019, em Los Angeles, quando cinco replicantes chegam à Terra, o ex-Blade Runner, Deckard, é encarregado de caçá-los.', '/y5ibL0vFnzsRiIHosw0WOfHtIj1.jpg', '1982-06-25', '[878,18,53]', 13.36, '2026-05-12 06:06:55'),
(368, 1254808, 'Nouvelle Vague', 'Acontece de tudo nos bastidores das filmagens de Acossado, de Jean-Luc Godard, um marco do movimento cinematográfico francês Nouvelle Vague.', '/2mGChnRQd75pOWU18B26KlxFMah.jpg', '2025-10-08', '[35,18,36]', 11.37, '2026-05-12 06:06:56'),
(369, 300496, 'Nefeli', '', '/4EgkcisexFjGfQmGI0IrVxZUBIv.jpg', '1980-01-01', '[10749]', 9.60, '2026-05-12 06:06:56'),
(370, 489, 'Gênio Indomável', 'Um professor do MIT descobre que um faxineiro da universidade é um gênio da matemática, e um psicólogo pouco ortodoxo ajuda o jovem a desenvolver seu potencial.', '/dTe3EpJGnfUeR5swLbWv61iRyFc.jpg', '1997-12-05', '[18]', 12.48, '2026-05-12 06:06:57'),
(371, 519465, 'Rainha de Copas', 'Anne é uma advogada do direito das crianças e dos adolescentes. Acostumada com lidar com jovens complicados, ela não tem muitas dificuldades para estreitar laços com seu enteado Gustav, filho do primeiro casamento de seu marido Peter que acaba de se mudar para sua casa. No entanto, a relação que deveria ser paternal se torna uma relação romântica, envolvendo Anna em uma situação complexa, arriscando a estabilidade tanto de sua vida pessoal quanto profissional.', '/8YIrayzSOlrfSfZvghfpry3pjMU.jpg', '2019-03-27', '[18]', 12.05, '2026-05-12 06:06:57'),
(372, 2832, 'Identidade', 'Uma violenta tempestade faz com que um grupo de pessoas busque abrigo em um motel desolado, gerenciado por um jovem bastante nervoso. De início todos se sentem aliviados por encontrarem um lugar para ficar em meio à tempestade, mas logo entram em pânico ao perceber que, um a um, todos estão sendo assassinados em nome de um misterioso segredo que une a presença de todos naquele lugar.', '/nnRUp7GRtLY188akcwBAnQzByXd.jpg', '2003-04-25', '[9648,53]', 12.24, '2026-05-12 06:06:58'),
(373, 150689, 'Cinderela', 'Após a trágica e inesperada morte do seu pai, Ella (Lily James) fica à mercê da sua terrível madrasta, Lady Tremaine (Cate Blanchett), e suas filhas Anastasia e Drisella. A jovem ganha o apelido de Cinderela e é obrigada a trabalhar como empregada na sua própria casa, mas continua otimista com a vida. Passeando na floresta, ela se encanta por um corajoso estranho (Richard Madden), sem desconfiar que ele é o príncipe do castelo. Cinderela recebe um convite para o grande baile e acredita que pode voltar a encontrar sua alma gêmea, mas seus planos vão por água abaixo quando a madrasta má rasga seu vestido. Agora, será preciso uma fada madrinha (Helena Bonham Carter) para mudar o seu destino.', '/x8MnNc8zaKMPo5W4TuWN0xVIbNy.jpg', '2015-03-06', '[10749,14,10751,18]', 14.04, '2026-05-12 06:06:58'),
(374, 1034541, 'Terrifier 3', 'O palhaço assassino Art está pronto para espalhar o caos sobre os moradores inocentes do Condado de Miles durante uma pacífica véspera de Natal.', '/3HeKb5H89HjzWTkVkAqomu9mek.jpg', '2024-10-09', '[27]', 11.76, '2026-05-12 06:06:58'),
(375, 311, 'Era Uma Vez na América', 'Depois de crescer no gueto judeu de Nova Iorque e se destacar no crime organizado da Era da Proibição, um gângster de idade retorna a Brooklyn para enfrentar seu passado.', '/ojfEiNOBX7eqh4fDhRhNDTwb38R.jpg', '1984-05-23', '[18,80]', 12.94, '2026-05-12 06:06:59'),
(376, 1003596, 'Vingadores: Doutor Destino', 'Os Vingadores, Wakandanos, Quarteto Fantástico, Thunderbolts e X-Men lutam contra o Doutor Destino. Enredo a ser definido.', '/i29O7K4n3z5qB2SAJmSc0kR5dPj.jpg', '2026-12-16', '[878,28,12]', 14.71, '2026-05-12 06:06:59'),
(377, 62029, 'Bingo Bongo', '', '/cqiWWn2tnQwJHFmAMaLR2JdRbzC.jpg', '1982-12-23', '[35]', 11.23, '2026-05-12 06:06:59'),
(378, 585534, 'モーニング・ムーンは粗雑に', '', '/ogRSqsyiiQOxPXQR6y2WUMwcMb8.jpg', '1981-06-21', '[18]', 8.10, '2026-05-12 06:06:59'),
(379, 932086, 'Horizon: Uma Saga Americana - Capítulo 1', 'Explore a atração do Velho Oeste e como ele foi conquistado - e perdido - com o sangue, o suor e as lágrimas de muitos. Abrangendo os quatro anos da Guerra Civil, de 1861 a 1865, embarque em uma jornada emocionante por um país em guerra consigo mesmo, vivenciada pelas lentes de famílias, amigos e inimigos, todos tentando descobrir o que realmente significa ser os Estados Unidos da América.', '/wScEgkA3eWfhyp5WoxGt5Zu3sug.jpg', '2024-06-26', '[37,18]', 12.21, '2026-05-12 06:06:59'),
(380, 637, 'A Vida é Bela', 'Durante a Segunda Guerra Mundial na Itália, o judeu Guido e seu filho Giosué são levados para um campo de concentração nazista. Afastado da mulher, ele tem que usar sua imaginação para fazer o menino acreditar que estão participando de uma grande brincadeira, com o intuito de protegê-lo do terror e da violência que os cercam.', '/dkK48wCY4aVpWFDdPpS6DxQ1bvB.jpg', '1997-12-20', '[35,18]', 13.11, '2026-05-12 06:07:00'),
(381, 1043197, 'O Monstro do Meu Quarto', 'Aurora, uma menina de 10 anos, tem um vizinho misterioso que mata monstros da vida real. Ele é um assassino de aluguel. Então, quando Aurora precisa de ajuda para matar o monstro que ela acredita ter devorado toda a sua família, ela contrata os serviços dele. Suspeitando que seus pais possam ter sido vítimas de assassinos que o perseguiam, o vizinho de Aurora aceita o trabalho, sentindo-se culpado. Agora, para protegê-la, ele precisará lutar contra uma horda de assassinos — e aceitar que alguns monstros são reais.', '/cvdCMFP0pNYXtWXVuRD5Hqp6vuT.jpg', '2025-12-11', '[14,28,27]', 11.52, '2026-05-12 06:07:00');
